import React, { useState, useEffect } from 'react';
import DynamicCards from '../../components/dynamic-cards/DynamicCards';
import ProgressBar from '../../components/progress-bar/ProgressBar';
import { dashboardService, DashboardCategory } from '../../services/dashboardService';
import { Card, CardContent } from '../../components/ui/card';
import './AdminDashboard.css';

const AdminDashboard: React.FC = () => {
  const [categories, setCategories] = useState<DashboardCategory[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [mounted, setMounted] = useState(false);

  useEffect(() => {
    loadCategories();
  }, []);

  useEffect(() => {
    if (!loading) {
      const timer = setTimeout(() => setMounted(true), 50);
      return () => clearTimeout(timer);
    }
  }, [loading]);

  const loadCategories = async (showLoader = true) => {
    try {
      if (showLoader) {
        setLoading(true);
        setError(null);
      }
      const response = await dashboardService.getDashboardStatistics();
      setCategories(response.categories || []);
    } catch (err) {
      console.error('Error loading dashboard statistics:', err);
      if (showLoader) setError('Failed to load dashboard data');
    } finally {
      if (showLoader) setLoading(false);
    }
  };

  if (loading) {
    return (
      <div className="admin-dashboard">
        <div className="loading-container">
          <p>Loading...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="admin-dashboard">
        <div className="dashboard-header">
          <h2 className="dashboard-title">Dashboard</h2>
        </div>
        <Card className="error-card">
          <CardContent className="error-content">
            <p className="error-message">{error}</p>
            <button onClick={() => loadCategories()} className="retry-btn">
              Retry
            </button>
          </CardContent>
        </Card>
      </div>
    );
  }

  // Calculate total parameters count
  const totalParameters = categories.reduce((sum, cat) => sum + (cat.parameterCount || 0), 0);

  return (
    <div className="admin-dashboard">
      <div className="dashboard-split">
        {/* Left: scrollable content */}
        <div className="dashboard-left">
          <div
            style={{
              opacity: mounted ? 1 : 0,
              transform: mounted ? 'translateY(0)' : 'translateY(-15px)',
              transition: 'opacity 600ms ease-out, transform 600ms ease-out',
            }}
          >
            <div className="dashboard-header">
              <h2 className="dashboard-title">Dashboard</h2>
              <p className="dashboard-subtitle">Strategic Management Overview</p>
            </div>
          </div>

          <div
            style={{
              opacity: mounted ? 1 : 0,
              transform: mounted ? 'translateY(0)' : 'translateY(15px)',
              transition: 'opacity 500ms ease-out 150ms, transform 500ms ease-out 150ms',
            }}
          >
            <div className="section-header">
              <h3 className="section-title">Categories Overview</h3>
              <span className="total-params-badge">{totalParameters} Parameters</span>
            </div>
          </div>

          <div
            className="dashboard-content"
            style={{
              opacity: mounted ? 1 : 0,
              transform: mounted ? 'translateY(0)' : 'translateY(20px)',
              transition: 'opacity 700ms ease-out 300ms, transform 700ms ease-out 300ms',
            }}
          >
            <div className="categories-section">
              <DynamicCards categories={categories} className="dashboard-cards" onRefresh={() => loadCategories(false)} />
            </div>
          </div>
        </div>

        {/* Right: fixed strategic diagram */}
        <div className="dashboard-right">
          <div
            className="strategic-panel"
            style={{
              opacity: mounted ? 1 : 0,
              transform: mounted ? 'translateX(0) scale(1)' : 'translateX(40px) scale(0.97)',
              transition: 'opacity 1000ms ease-out 100ms, transform 1000ms ease-out 100ms',
            }}
          >
            <img
              src={require('../../assets/strategic-diagram.jpg')}
              alt="NED University Strategic Plan"
              className="strategic-panel-img"
            />
          </div>
        </div>
      </div>
    </div>
  );
};

export default AdminDashboard;