import React, { useState, useEffect, useCallback } from 'react';
import toast from 'react-hot-toast';
import editRequestService, { EditRequest } from '../../../services/editRequestService';
import './EditRequests.css';

const EditRequests: React.FC = () => {
  const [requests, setRequests] = useState<EditRequest[]>([]);
  const [loading, setLoading] = useState(true);
  const [actionLoading, setActionLoading] = useState<string | null>(null);

  const fetchRequests = useCallback(async () => {
    try {
      const data = await editRequestService.getAllRequests();
      setRequests(data);
    } catch (err: any) {
      toast.error(err.message || 'Failed to load requests');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchRequests();
  }, [fetchRequests]);

  const handleApprove = async (id: string) => {
    setActionLoading(id + '-approve');
    try {
      await editRequestService.approveRequest(id);
      toast.success('Request approved — targets unlocked');
      fetchRequests();
    } catch (err: any) {
      toast.error(err.message || 'Failed to approve');
    } finally {
      setActionLoading(null);
    }
  };

  const handleReject = async (id: string) => {
    setActionLoading(id + '-reject');
    try {
      await editRequestService.rejectRequest(id);
      toast.success('Request rejected');
      fetchRequests();
    } catch (err: any) {
      toast.error(err.message || 'Failed to reject');
    } finally {
      setActionLoading(null);
    }
  };

  const pending = requests.filter(r => r.status === 'pending');
  const resolved = requests.filter(r => r.status !== 'pending');

  const formatDate = (dateStr: string) =>
    new Date(dateStr).toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' });

  const renderTable = (items: EditRequest[], showActions: boolean) => (
    <table className="p-datatable-table">
      <thead className="p-datatable-thead">
        <tr>
          <th>Parameter</th>
          <th>Type</th>
          <th>User</th>
          <th>Reason</th>
          <th>Requested</th>
          {showActions ? <th>Actions</th> : <th>Status</th>}
        </tr>
      </thead>
      <tbody className="p-datatable-tbody">
        {items.length === 0 ? (
          <tr>
            <td colSpan={6}>No requests found.</td>
          </tr>
        ) : items.map(req => (
          <tr key={req._id}>
            <td><strong>{req.parameterName}</strong></td>
            <td>
              <span className={`er-type-badge er-type-${req.requestType}`}>
                {req.requestType === 'target' ? 'Target' : `Achieved (${req.year})`}
              </span>
            </td>
            <td>
              <div>{req.userName}</div>
              <div className="er-user-email">{req.userEmail}</div>
            </td>
            <td>{req.reason}</td>
            <td>{formatDate(req.createdAt)}</td>
            {showActions ? (
              <td>
                <div className="action-buttons">
                  <button
                    className="er-btn er-btn-approve"
                    onClick={() => handleApprove(req._id)}
                    disabled={!!actionLoading}
                  >
                    {actionLoading === req._id + '-approve' ? 'Approving...' : 'Approve'}
                  </button>
                  <button
                    className="er-btn er-btn-reject"
                    onClick={() => handleReject(req._id)}
                    disabled={!!actionLoading}
                  >
                    {actionLoading === req._id + '-reject' ? 'Rejecting...' : 'Reject'}
                  </button>
                </div>
              </td>
            ) : (
              <td>
                <span className={`er-status-badge er-status-${req.status}`}>
                  {req.status.charAt(0).toUpperCase() + req.status.slice(1)}
                </span>
              </td>
            )}
          </tr>
        ))}
      </tbody>
    </table>
  );

  return (
    <div className="er-page">
      <div className="er-header">
        <h2 className="er-title">Edit Requests</h2>
        <span className="er-pending-badge">{pending.length} Pending</span>
      </div>

      {loading ? (
        <div className="er-loading">Loading...</div>
      ) : (
        <>
          <div className="er-section">
            <h3 className="er-section-title">Pending</h3>
            <div className="p-datatable er-datatable">
              {renderTable(pending, true)}
            </div>
          </div>

          <div className="er-section">
            <h3 className="er-section-title">Resolved</h3>
            <div className="p-datatable er-datatable">
              {renderTable(resolved, false)}
            </div>
          </div>
        </>
      )}
    </div>
  );
};

export default EditRequests;
