import React, { useState, useMemo, useEffect } from 'react';
import { Loader2, ChevronUp, Lock, Target, BarChart3, TrendingUp, TrendingDown, AlertTriangle, Edit2 } from 'lucide-react';
import { ParameterDetails, FormValues, CycleInfo } from './ParameterListView';
import editRequestService, { EditRequest } from '../../services/editRequestService';

interface ExpandableParameterFormProps {
  parameterDetails: ParameterDetails;
  onSubmit: (parameterId: number, cycle: number, values: FormValues) => Promise<boolean>;
  onSubmitTargets: (parameterId: number, targetValues: { year: number; value: number | string }[], overallTarget: number | null) => Promise<boolean>;
  onCollapse: () => void;
  isSubmitting: boolean;
}

const ExpandableParameterForm: React.FC<ExpandableParameterFormProps> = ({
  parameterDetails,
  onSubmit,
  onSubmitTargets,
  onCollapse,
  isSubmitting
}) => {
  const { parameter, allCycleYears, cycles, targetValuesLocked, unlockedAchievedYears = [], overallTarget: savedOverallTarget, submittedValues } = parameterDetails;

  // Target values form state
  const [overallTargetInput, setOverallTargetInput] = useState<string>(
    savedOverallTarget !== null && savedOverallTarget !== undefined ? savedOverallTarget.toString() : ''
  );
  const [targetFormValues, setTargetFormValues] = useState<{ [year: number]: string }>({});
  const [targetErrors, setTargetErrors] = useState<string>('');

  // Actual values form state
  const [actualFormValues, setActualFormValues] = useState<{ [cycle: number]: FormValues }>({});
  const [actualErrors, setActualErrors] = useState<{ [cycle: number]: string }>({});
  const [isEditing, setIsEditing] = useState<{ [cycle: number]: boolean }>({});

  // Edit request state — all requests for this parameter
  const [allMyRequests, setAllMyRequests] = useState<EditRequest[]>([]);
  // target request UI
  const [showTargetRequestForm, setShowTargetRequestForm] = useState(false);
  const [targetRequestReason, setTargetRequestReason] = useState('');
  const [targetRequestSubmitting, setTargetRequestSubmitting] = useState(false);
  const [targetRequestError, setTargetRequestError] = useState('');
  // achieved request UI — per year
  const [showAchievedRequestForm, setShowAchievedRequestForm] = useState<{ [year: number]: boolean }>({});
  const [achievedRequestReason, setAchievedRequestReason] = useState<{ [year: number]: string }>({});
  const [achievedRequestSubmitting, setAchievedRequestSubmitting] = useState<{ [year: number]: boolean }>({});
  const [achievedRequestError, setAchievedRequestError] = useState<{ [year: number]: string }>({});

  // Load all edit requests for this parameter
  const loadMyRequests = () => {
    if (!targetValuesLocked) return;
    editRequestService.getMyRequests(parameter.id).then(reqs => {
      setAllMyRequests(reqs);
    }).catch(() => {});
  };

  useEffect(() => {
    loadMyRequests();
  }, [parameter.id, targetValuesLocked]); // eslint-disable-line react-hooks/exhaustive-deps

  // Get latest active request by type (+year for achieved)
  // Approved requests are excluded once the targets/value are re-locked (consumed)
  const getTargetRequest = (): EditRequest | null => {
    const reqs = allMyRequests.filter(r => r.requestType === 'target' && r.status !== 'approved');
    return reqs.length > 0 ? reqs[0] : null;
  };

  const getAchievedRequest = (year: number): EditRequest | null => {
    // Only show pending/rejected — approved is consumed once the year is re-locked
    const reqs = allMyRequests.filter(r =>
      r.requestType === 'achieved' && r.year === year && r.status !== 'approved'
    );
    return reqs.length > 0 ? reqs[0] : null;
  };

  const handleSubmitTargetRequest = async () => {
    if (!targetRequestReason.trim()) {
      setTargetRequestError('Please enter a reason for your edit request.');
      return;
    }
    setTargetRequestSubmitting(true);
    setTargetRequestError('');
    try {
      await editRequestService.submitRequest(parameter.id, targetRequestReason.trim(), 'target');
      loadMyRequests();
      setShowTargetRequestForm(false);
      setTargetRequestReason('');
    } catch (err: any) {
      setTargetRequestError(err.message || 'Failed to submit request');
    } finally {
      setTargetRequestSubmitting(false);
    }
  };

  const handleSubmitAchievedRequest = async (year: number) => {
    const reason = achievedRequestReason[year] || '';
    if (!reason.trim()) {
      setAchievedRequestError(prev => ({ ...prev, [year]: 'Please enter a reason.' }));
      return;
    }
    setAchievedRequestSubmitting(prev => ({ ...prev, [year]: true }));
    setAchievedRequestError(prev => ({ ...prev, [year]: '' }));
    try {
      await editRequestService.submitRequest(parameter.id, reason.trim(), 'achieved', year);
      loadMyRequests();
      setShowAchievedRequestForm(prev => ({ ...prev, [year]: false }));
      setAchievedRequestReason(prev => ({ ...prev, [year]: '' }));
    } catch (err: any) {
      setAchievedRequestError(prev => ({ ...prev, [year]: err.message || 'Failed to submit request' }));
    } finally {
      setAchievedRequestSubmitting(prev => ({ ...prev, [year]: false }));
    }
  };

  const isTextType = parameter.parameterType === 'Text';

  // --- TARGET VALUES SECTION ---

  const lastYear = allCycleYears[allCycleYears.length - 1];
  const firstYear = allCycleYears[0];

  const handleOverallTargetChange = (value: string) => {
    setOverallTargetInput(value);
    // Auto-sync: fill the last year cell with the same value
    if (lastYear !== undefined) {
      setTargetFormValues(prev => ({ ...prev, [lastYear]: value }));
    }
    if (targetErrors) setTargetErrors('');
  };

  const handleTargetInputChange = (year: number, value: string) => {
    setTargetFormValues(prev => ({ ...prev, [year]: value }));
    // Auto-sync: if user types in last year cell, update the overall target box too
    if (year === lastYear) {
      setOverallTargetInput(value);
    }
    if (targetErrors) setTargetErrors('');
  };

  const getTargetDisplayValue = (year: number): string => {
    // Only show submitted projected values when targets are locked (new-style submission)
    if (!targetValuesLocked) return '';
    const submitted = submittedValues[year];
    if (submitted) {
      if (isTextType && submitted.textValue) return submitted.textValue;
      if (submitted.projectedValue !== undefined && submitted.projectedValue !== null) {
        return submitted.projectedValue.toString();
      }
    }
    return '';
  };

  const getTargetInputValue = (year: number): string => {
    if (targetFormValues[year] !== undefined) return targetFormValues[year];
    return getTargetDisplayValue(year);
  };

  const parsedOverallTarget = Number(overallTargetInput);
  const isOverallTargetValid = !isNaN(parsedOverallTarget) && parsedOverallTarget > 0;

  const isDecreasing = parameter.isDecreasing === true;

  // Check direction rule across all years
  // For increasing params: each year must be >= previous (non-decreasing)
  // For decreasing params: each year must be <= previous (non-increasing)
  // Returns the first year that violates the rule, or null
  const getDirectionViolation = (): number | null => {
    if (isTextType) return null;
    for (let i = 1; i < allCycleYears.length; i++) {
      const prevYear = allCycleYears[i - 1];
      const currYear = allCycleYears[i];
      const prevVal = getTargetInputValue(prevYear);
      const currVal = getTargetInputValue(currYear);
      if (prevVal === '' || currVal === '') continue;
      if (isDecreasing) {
        // Violation: value went UP when it should decrease or stay same
        if (Number(currVal) > Number(prevVal)) return currYear;
      } else {
        // Violation: value went DOWN when it should increase or stay same
        if (Number(currVal) < Number(prevVal)) return currYear;
      }
    }
    return null;
  };

  const directionViolation = isTextType ? null : getDirectionViolation();

  const handleSubmitAllTargets = async () => {
    const missing: number[] = [];
    const targetValues: { year: number; value: number | string }[] = [];

    // Validate overallTarget for numeric types
    if (!isTextType) {
      if (!overallTargetInput || !isOverallTargetValid) {
        setTargetErrors('Please enter a valid overall target value first.');
        return;
      }
      // For increasing params: overall target must not exceed maxValue (it's a ceiling)
      // For decreasing params: overall target is the minimum to reach — maxValue is still the ceiling for any individual year
      if (!isDecreasing && parsedOverallTarget > parameter.maxValue) {
        setTargetErrors(`Overall target cannot exceed the maximum value of ${parameter.maxValue}`);
        return;
      }
    }

    for (const year of allCycleYears) {
      const val = targetFormValues[year] !== undefined ? targetFormValues[year] : getTargetDisplayValue(year);

      if (!val && val !== '0') {
        missing.push(year);
        continue;
      }

      if (isTextType) {
        targetValues.push({ year, value: val });
      } else {
        const numVal = Number(val);
        if (isNaN(numVal)) {
          setTargetErrors(`Invalid number for year ${year}`);
          return;
        }
        if (numVal < 0) {
          setTargetErrors(`Year ${year}: value cannot be negative`);
          return;
        }
        targetValues.push({ year, value: numVal });
      }
    }

    if (missing.length > 0) {
      setTargetErrors(`Please fill target values for all years. Missing: ${missing.join(', ')}`);
      return;
    }

    // Validate direction rule
    if (!isTextType && directionViolation !== null) {
      const prevIdx = allCycleYears.indexOf(directionViolation) - 1;
      const prevYear = allCycleYears[prevIdx];
      setTargetErrors(
        isDecreasing
          ? `Year ${directionViolation} value cannot be higher than ${prevYear}'s value. Targets must decrease or stay the same.`
          : `Year ${directionViolation} value cannot be less than ${prevYear}'s value. Targets must increase or stay the same.`
      );
      return;
    }

    await onSubmitTargets(parameter.id, targetValues, isTextType ? null : parsedOverallTarget);
  };

  // --- ACTUAL VALUES SECTION ---

  const handleActualInputChange = (cycle: number, field: keyof FormValues, value: string) => {
    setActualFormValues(prev => ({
      ...prev,
      [cycle]: {
        ...prev[cycle],
        [field]: field === 'textValue' ? value : (value !== '' ? Number(value) : undefined)
      }
    }));
    if (actualErrors[cycle]) {
      setActualErrors(prev => ({ ...prev, [cycle]: '' }));
    }
  };

  const validateActualForm = (cycle: number): boolean => {
    const values = actualFormValues[cycle];
    if (!values || (values.actualValue === undefined && !values.textValue)) {
      setActualErrors(prev => ({ ...prev, [cycle]: 'Please enter a value' }));
      return false;
    }

    if (!isTextType) {
      const val = values.actualValue;
      if (val !== undefined && (val < 0 || val > parameter.maxValue)) {
        setActualErrors(prev => ({ ...prev, [cycle]: `Value must be between 0 and ${parameter.maxValue}` }));
        return false;
      }
    }

    return true;
  };

  const handleSubmitActual = async (cycle: number) => {
    if (validateActualForm(cycle)) {
      const success = await onSubmit(parameter.id, cycle, actualFormValues[cycle] || {});
      if (success) {
        setIsEditing(prev => ({ ...prev, [cycle]: false }));
        // Reload requests so the "Request Edit" button reappears after re-submission
        loadMyRequests();
      }
    }
  };

  const handleEditActual = (cycle: number) => {
    setIsEditing(prev => ({ ...prev, [cycle]: true }));
    const submitted = submittedValues[cycle];
    if (submitted) {
      setActualFormValues(prev => ({
        ...prev,
        [cycle]: {
          actualValue: submitted.actualValue,
          textValue: submitted.textValue,
        }
      }));
    }
  };

  const handleCancelEdit = (cycle: number) => {
    setIsEditing(prev => ({ ...prev, [cycle]: false }));
    setActualErrors(prev => ({ ...prev, [cycle]: '' }));
  };

  const getActualInputValue = (cycle: number, field: keyof FormValues): string => {
    const formVal = actualFormValues[cycle]?.[field];
    if (formVal !== undefined && formVal !== null) return formVal.toString();
    const submitted = submittedValues[cycle]?.[field];
    if (submitted !== undefined && submitted !== null) return submitted.toString();
    return '';
  };

  const isActualSubmitted = (cycle: number): boolean => {
    const sv = submittedValues[cycle];
    if (!sv) return false;
    if (isTextType) return !!(sv.textValue);
    return sv.actualValue !== undefined && sv.actualValue !== null;
  };

  const isActualFieldDisabled = (cycle: number): boolean => {
    // If admin has unlocked this year, allow editing
    if (unlockedAchievedYears.includes(cycle)) return false;
    // If in editing mode (unlocked), allow
    if (isEditing[cycle]) return false;
    // Otherwise lock once submitted
    return isActualSubmitted(cycle);
  };

  const handleSubmitAllActuals = async () => {
    const toSubmit: { cycle: number; values: FormValues }[] = [];

    for (const cycleInfo of cycles) {
      if (cycleInfo.year === firstYear) continue;
      if (!cycleInfo.enabled) continue;
      if (isActualFieldDisabled(cycleInfo.year)) continue;

      const values = actualFormValues[cycleInfo.year];
      if (values && (values.actualValue !== undefined || values.textValue)) {
        if (!validateActualForm(cycleInfo.year)) return;
        toSubmit.push({ cycle: cycleInfo.year, values });
      }
    }

    if (toSubmit.length === 0) {
      return;
    }

    for (const { cycle, values } of toSubmit) {
      await onSubmit(parameter.id, cycle, values);
    }
  };

  // --- CUMULATIVE BACKLOG TRACKING ---

  // Compute cumulative stats — two-layer model:
  // Targets are running totals (e.g. 10→13→16→20→22→25)
  // firstYear is baseline (no actual submission), subsequent years have actuals
  // yearGainTarget = targetThisYear - targetPrevYear (how much was planned to be added)
  // yearGainActual = actualThisYear - actualPrevYear (how much was actually added)
  const cumulativeStats = useMemo(() => {
    if (isTextType || !targetValuesLocked) return {};

    const allYears = allCycleYears.slice().sort((a, b) => a - b);
    const enabledYears = cycles.filter(c => c.enabled || isActualSubmitted(c.year)).map(c => c.year).sort((a, b) => a - b);

    const stats: { [year: number]: {
      // Running total targets
      targetTotal: number;
      actualTotal: number | null;
      // Gain this year vs previous year
      gainTarget: number;       // target increase from prev year
      gainActual: number | null; // actual increase from prev year
      gainDiff: number | null;   // gainActual - gainTarget
      // Cumulative gap (actualTotal vs targetTotal)
      cumulDiff: number | null;
      isSubmitted: boolean;
      isBaseline: boolean;
    }} = {};

    for (let i = 0; i < allYears.length; i++) {
      const year = allYears[i];
      if (!enabledYears.includes(year) && year !== firstYear) continue;

      const targetTotal = Number(getTargetDisplayValue(year)) || 0;
      const sv = submittedValues[year];
      const hasActual = sv && sv.actualValue !== undefined && sv.actualValue !== null;
      const actualTotal = hasActual ? Number(sv.actualValue) : null;

      const isBase = year === firstYear;

      // Gain vs previous year
      let gainTarget = 0;
      let gainActual: number | null = null;
      let gainDiff: number | null = null;

      if (i > 0) {
        const prevYear = allYears[i - 1];
        const prevTargetTotal = Number(getTargetDisplayValue(prevYear)) || 0;
        gainTarget = targetTotal - prevTargetTotal;

        // For actual gain: use prev year's actual if available, else prev year's target as baseline
        const prevSv = submittedValues[prevYear];
        const prevActualTotal = (prevSv && prevSv.actualValue !== undefined && prevSv.actualValue !== null)
          ? Number(prevSv.actualValue)
          : (prevYear === firstYear ? prevTargetTotal : null); // baseline year uses its target as the starting point

        if (hasActual && prevActualTotal !== null) {
          gainActual = actualTotal! - prevActualTotal;
          gainDiff = gainActual - gainTarget;
        }
      }

      stats[year] = {
        targetTotal,
        actualTotal,
        gainTarget,
        gainActual,
        gainDiff,
        cumulDiff: hasActual && actualTotal !== null ? actualTotal - targetTotal : null,
        isSubmitted: !!hasActual,
        isBaseline: isBase,
      };
    }

    return stats;
  }, [cycles, submittedValues, targetValuesLocked, isTextType, allCycleYears, firstYear]);

  // Overall progress — uses latest submitted actual vs overall target (running totals model)
  const overallProgress = useMemo(() => {
    if (isTextType || !targetValuesLocked || !savedOverallTarget) return null;

    const enabledYears = cycles.filter(c => c.enabled || isActualSubmitted(c.year)).map(c => c.year).sort((a, b) => a - b);
    let latestActual: number | null = null;
    let latestActualYear: number | null = null;
    let submittedCount = 0;

    for (const year of enabledYears) {
      if (year === firstYear) continue; // skip baseline
      const sv = submittedValues[year];
      if (sv && sv.actualValue !== undefined && sv.actualValue !== null) {
        latestActual = Number(sv.actualValue);
        latestActualYear = year;
        submittedCount++;
      }
    }

    if (submittedCount === 0 || latestActual === null) return null;

    let percentage: number;
    let diff: number;

    if (isDecreasing) {
      // Decreasing parameter: progress = how much we've reduced vs total reduction needed
      // Baseline = the first year's target value (the starting point)
      const baseline = Number(getTargetDisplayValue(firstYear)) || latestActual;
      const totalReductionNeeded = baseline - savedOverallTarget; // e.g. 12 - 5 = 7
      const reductionAchieved = baseline - latestActual;          // e.g. 12 - 12 = 0
      percentage = totalReductionNeeded > 0
        ? Math.round((reductionAchieved / totalReductionNeeded) * 100)
        : 0;
      // diff > 0 = latestActual < overallTarget = gone below final target = AHEAD
      // diff < 0 = latestActual > overallTarget = still above final target = BEHIND
      diff = savedOverallTarget - latestActual;
    } else {
      // Increasing parameter (default)
      percentage = savedOverallTarget > 0 ? Math.round((latestActual / savedOverallTarget) * 100) : 0;
      diff = latestActual - savedOverallTarget;
    }

    return {
      latestActual,
      latestActualYear,
      overallTarget: savedOverallTarget,
      diff,
      percentage,
      submittedCount,
      totalYears: enabledYears.filter(y => y !== firstYear).length,
    };
  }, [cycles, submittedValues, targetValuesLocked, savedOverallTarget, isTextType, firstYear, isDecreasing]);

  // --- RENDER ---

  return (
    <div className="expandable-parameter-form">
      {/* Parameter Header */}
      <div className="parameter-form-header">
        <h4>{parameter.name}</h4>
        <p className="form-description">{parameter.description}</p>
        <div className="form-meta">
          <span className="form-meta-tag">Type: {parameter.parameterType}</span>
          <span className="form-meta-tag">Max Value: {parameter.maxValue}</span>
          {isDecreasing && (
            <span className="form-meta-tag" style={{ background: 'rgba(239,68,68,0.12)', color: '#ef4444' }}>
              📉 Lower is better
            </span>
          )}
        </div>
      </div>

      {/* SECTION A: Strategic Target Values */}
      <div className={`target-values-section ${targetValuesLocked ? 'locked' : 'unlocked'}`}>
        <div className="section-header">
          <div className="section-title-row">
            <Target size={18} className="section-icon" />
            <h5 className="section-title">Strategic Targets ({allCycleYears.length}-Year Plan)</h5>
          </div>
          {targetValuesLocked ? (
            <span className="status-badge status-locked">
              <Lock size={12} />
              Locked
            </span>
          ) : (
            <span className="status-badge status-pending">
              Pending
            </span>
          )}
        </div>

        {/* Overall Target Input (numeric only) */}
        {!isTextType && (
          <div className="overall-target-row">
            <div className="overall-target-label">
              <Target size={16} />
              <span>Overall Target ({allCycleYears[allCycleYears.length - 1]})</span>
            </div>
            {targetValuesLocked ? (
              <div className="overall-target-locked">
                {savedOverallTarget ?? '—'}
              </div>
            ) : (
              <div className="overall-target-input-wrapper">
                <input
                  type="number"
                  className="overall-target-input"
                  value={overallTargetInput}
                  onChange={(e) => handleOverallTargetChange(e.target.value)}
                  placeholder="Enter overall target"
                  min="0"
                  max={parameter.maxValue}
                  disabled={isSubmitting}
                />
                <span className="overall-target-hint">
                  Max: {parameter.maxValue}
                </span>
              </div>
            )}
          </div>
        )}

        {/* Yearly Target Inputs */}
        <div className="target-values-grid">
          {allCycleYears.map(year => {
            const displayVal = getTargetDisplayValue(year);
            const inputVal = getTargetInputValue(year);

            const isBaseline = year === firstYear;

            return (
              <div key={year} className={`target-year-item${isBaseline ? ' baseline-year-item' : ''}`}>
                <label className={`target-year-label${isBaseline ? ' baseline-year-label' : ''}`}>
                  {year}
                </label>
                {targetValuesLocked ? (
                  <div className={`target-value-locked${isBaseline ? ' baseline-value-locked' : ''}`}>
                    {displayVal || '—'}
                  </div>
                ) : (
                  isTextType ? (
                    <textarea
                      className={`target-input target-textarea${isBaseline ? ' baseline-input' : ''}`}
                      value={inputVal}
                      onChange={(e) => handleTargetInputChange(year, e.target.value)}
                      placeholder={isBaseline ? `Current value as of ${year}` : `Target for ${year}`}
                      rows={2}
                      disabled={isSubmitting}
                    />
                  ) : (
                    <input
                      type="number"
                      className={`target-input${isBaseline ? ' baseline-input' : `${directionViolation === year ? ' target-input-error' : ''}`}`}
                      value={inputVal}
                      onChange={(e) => handleTargetInputChange(year, e.target.value)}
                      placeholder={isBaseline ? 'Current value' : '0'}
                      min="0"
                      disabled={isSubmitting || (!isBaseline && !isOverallTargetValid)}
                    />
                  )
                )}
                {isBaseline && (
                  <span className="baseline-subtext">{targetValuesLocked ? `Actual value in ${year}` : `Enter actual value in ${year}`}</span>
                )}
                {!isBaseline && !isTextType && (
                  <span className="target-year-subtext">Cumulative target value in {year}</span>
                )}
              </div>
            );
          })}
        </div>

        {/* Direction validator (numeric only, not locked) */}
        {!isTextType && !targetValuesLocked && directionViolation !== null && (
          <div className="nondecreasing-warning">
            <AlertTriangle size={14} />
            {isDecreasing
              ? `Year ${directionViolation} cannot be higher than ${allCycleYears[allCycleYears.indexOf(directionViolation) - 1]}'s value. Targets must stay the same or decrease each year.`
              : `Year ${directionViolation} cannot be lower than ${allCycleYears[allCycleYears.indexOf(directionViolation) - 1]}'s value. Targets must stay the same or increase each year.`
            }
          </div>
        )}

        {targetErrors && (
          <div className="target-error-message">{targetErrors}</div>
        )}

        {!targetValuesLocked && (
          <div className="target-actions">
            <button
              type="button"
              className="btn btn-primary submit-targets-btn"
              onClick={handleSubmitAllTargets}
              disabled={isSubmitting || (!isTextType && (directionViolation !== null || !isOverallTargetValid))}
            >
              {isSubmitting ? (
                <>
                  <Loader2 className="animate-spin" size={14} />
                  Submitting...
                </>
              ) : (
                <>
                  <Lock size={14} />
                  Submit &amp; Lock All Targets
                </>
              )}
            </button>
            <p className="target-warning">
              Once submitted, target values cannot be changed.
            </p>
          </div>
        )}

        {/* Edit request UI — only when targets are locked */}
        {targetValuesLocked && (() => {
          const req = getTargetRequest();
          return (
            <div className="edit-request-section">
              {req?.status === 'pending' && (
                <div className="edit-request-status pending">
                  <Edit2 size={14} />
                  <span>Edit request pending admin approval</span>
                </div>
              )}
              {req?.status === 'rejected' && !showTargetRequestForm && (
                <div className="edit-request-rejected-row">
                  <span className="edit-request-status rejected">
                    <Edit2 size={14} />
                    Previous request was rejected
                  </span>
                  <button type="button" className="btn-request-edit" onClick={() => setShowTargetRequestForm(true)}>
                    Request Edit Again
                  </button>
                </div>
              )}
              {!req && !showTargetRequestForm && (
                <button type="button" className="btn-request-edit" onClick={() => setShowTargetRequestForm(true)}>
                  <Edit2 size={13} />
                  Request to Edit Targets
                </button>
              )}
              {showTargetRequestForm && (
                <div className="edit-request-form">
                  <label className="edit-request-label">Reason for edit request</label>
                  <textarea
                    className="edit-request-textarea"
                    value={targetRequestReason}
                    onChange={(e) => { setTargetRequestReason(e.target.value); setTargetRequestError(''); }}
                    placeholder="Briefly explain why you need to edit the targets..."
                    rows={3}
                    disabled={targetRequestSubmitting}
                  />
                  {targetRequestError && <div className="edit-request-error">{targetRequestError}</div>}
                  <div className="edit-request-actions">
                    <button type="button" className="btn btn-primary btn-sm" onClick={handleSubmitTargetRequest} disabled={targetRequestSubmitting}>
                      {targetRequestSubmitting ? <Loader2 className="animate-spin" size={13} /> : 'Submit Request'}
                    </button>
                    <button type="button" className="btn btn-secondary btn-sm" onClick={() => { setShowTargetRequestForm(false); setTargetRequestReason(''); setTargetRequestError(''); }} disabled={targetRequestSubmitting}>
                      Cancel
                    </button>
                  </div>
                </div>
              )}
            </div>
          );
        })()}
      </div>

      {/* SECTION B: Achieved Values */}
      <div className={`actual-values-section ${targetValuesLocked ? 'unlocked' : 'locked-overlay'}`}>
        <div className="section-header">
          <div className="section-title-row">
            <BarChart3 size={18} className="section-icon" />
            <h5 className="section-title">Achieved Values</h5>
          </div>
        </div>

        {!targetValuesLocked ? (
          <div className="actual-locked-message">
            <Lock size={20} />
            <p>Submit target values for all years to unlock achieved value submissions.</p>
          </div>
        ) : (
          <div className="actual-values-container">
            {/* Baseline reference row — read only, no submission */}
            {!isTextType && firstYear && (
              <div className="actual-year-row baseline-ref-row">
                <div className="actual-year-info">
                  <span className="actual-year-label">{firstYear}</span>
                  <span className="baseline-ref-label">Current total value in {firstYear}</span>
                </div>
                <div className="baseline-ref-value">
                  {getTargetDisplayValue(firstYear) || '—'}
                </div>
              </div>
            )}
            {cycles.filter(c => c.year !== firstYear && (c.enabled || isActualSubmitted(c.year))).map(cycleInfo => {
              const year = cycleInfo.year;
              const targetVal = getTargetDisplayValue(year);
              const submitted = isActualSubmitted(year);
              const disabled = isActualFieldDisabled(year);
              const stats = cumulativeStats[year];

              return (
                <div key={year} className={`actual-year-row ${submitted ? 'submitted' : ''}`}>
                  <div className="actual-year-info">
                    <span className="actual-year-label">{year}</span>
                    <span className="actual-target-ref">
                      Target: <strong>{targetVal || '—'}</strong>
                    </span>
                    
                  </div>

                  <div className="actual-input-area">
                    {isTextType ? (
                      <textarea
                        className={`actual-input actual-textarea ${submitted && !isEditing[year] ? 'read-only' : ''}`}
                        value={getActualInputValue(year, 'textValue')}
                        onChange={(e) => handleActualInputChange(year, 'textValue', e.target.value)}
                        disabled={disabled}
                        placeholder="Enter achieved value..."
                        rows={2}
                      />
                    ) : (
                      <div className="actual-numeric-input-wrapper">
                        <label className="actual-field-label">Achieved Value:</label>
                        <input
                          type="number"
                          className={`actual-input ${submitted && !isEditing[year] ? 'read-only' : ''}`}
                          value={getActualInputValue(year, 'actualValue')}
                          onChange={(e) => handleActualInputChange(year, 'actualValue', e.target.value)}
                          disabled={disabled}
                          placeholder="Enter achieved value"
                          min="0"
                          max={parameter.maxValue}
                        />
                      </div>
                    )}
                  </div>

                  {actualErrors[year] && (
                    <div className="actual-error">{actualErrors[year]}</div>
                  )}

                  <div className="actual-actions">
                    {/* Submit / Update button — shown when field is editable */}
                    {cycleInfo.enabled && (!submitted || unlockedAchievedYears.includes(year) || isEditing[year]) && !isActualFieldDisabled(year) && (
                      <button
                        type="button"
                        className="btn btn-primary btn-sm"
                        onClick={() => handleSubmitActual(year)}
                        disabled={isSubmitting}
                      >
                        {isSubmitting ? <Loader2 className="animate-spin" size={14} /> : (submitted ? 'Update' : 'Submit')}
                      </button>
                    )}
                    {/* Cancel edit button */}
                    {cycleInfo.enabled && isEditing[year] && (
                      <button
                        type="button"
                        className="btn btn-secondary btn-sm"
                        onClick={() => handleCancelEdit(year)}
                        disabled={isSubmitting}
                      >
                        Cancel
                      </button>
                    )}
                    {/* Request edit flow — shown when submitted and NOT unlocked */}
                    {submitted && !unlockedAchievedYears.includes(year) && !isEditing[year] && (() => {
                      const req = getAchievedRequest(year);
                      return (
                        <div className="achieved-request-area">
                          {req?.status === 'pending' && (
                            <span className="edit-request-status pending" style={{ fontSize: '0.75rem' }}>
                              <Edit2 size={12} /> Request pending
                            </span>
                          )}
                          {req?.status === 'rejected' && !showAchievedRequestForm[year] && (
                            <div className="edit-request-rejected-row">
                              <span className="edit-request-status rejected" style={{ fontSize: '0.75rem' }}>
                                <Edit2 size={12} /> Rejected
                              </span>
                              <button type="button" className="btn-request-edit" onClick={() => setShowAchievedRequestForm(prev => ({ ...prev, [year]: true }))}>
                                Request Again
                              </button>
                            </div>
                          )}
                          {!req && !showAchievedRequestForm[year] && (
                            <button type="button" className="btn-request-edit" onClick={() => setShowAchievedRequestForm(prev => ({ ...prev, [year]: true }))}>
                              <Edit2 size={12} /> Request Edit
                            </button>
                          )}
                          {showAchievedRequestForm[year] && (
                            <div className="edit-request-form">
                              <label className="edit-request-label">Reason</label>
                              <textarea
                                className="edit-request-textarea"
                                value={achievedRequestReason[year] || ''}
                                onChange={(e) => { setAchievedRequestReason(prev => ({ ...prev, [year]: e.target.value })); setAchievedRequestError(prev => ({ ...prev, [year]: '' })); }}
                                placeholder="Why do you need to edit this value?"
                                rows={2}
                                disabled={achievedRequestSubmitting[year]}
                              />
                              {achievedRequestError[year] && <div className="edit-request-error">{achievedRequestError[year]}</div>}
                              <div className="edit-request-actions">
                                <button type="button" className="btn btn-primary btn-sm" onClick={() => handleSubmitAchievedRequest(year)} disabled={achievedRequestSubmitting[year]}>
                                  {achievedRequestSubmitting[year] ? <Loader2 className="animate-spin" size={13} /> : 'Submit'}
                                </button>
                                <button type="button" className="btn btn-secondary btn-sm" onClick={() => { setShowAchievedRequestForm(prev => ({ ...prev, [year]: false })); setAchievedRequestError(prev => ({ ...prev, [year]: '' })); }} disabled={achievedRequestSubmitting[year]}>
                                  Cancel
                                </button>
                              </div>
                            </div>
                          )}
                        </div>
                      );
                    })()}
                  </div>

                  {submitted && !isEditing[year] && submittedValues[year] && (
                    <div className="actual-submission-info">
                      Submitted: {new Date(submittedValues[year].submittedAt).toLocaleDateString()}
                    </div>
                  )}

                  {/* Inline progress line */}
                  {!isTextType && stats && stats.isSubmitted && !isEditing[year] && stats.cumulDiff !== null && (
                    <div className={`inline-progress-line ${
                      isDecreasing
                        ? (stats.cumulDiff <= 0 ? 'surplus' : 'deficit')  // decreasing: actual below target = good
                        : (stats.cumulDiff >= 0 ? 'surplus' : 'deficit')  // increasing: actual above target = good
                    }`}>
                      {isDecreasing ? (
                        // Decreasing: cumulDiff = actual - target; negative = actual < target = AHEAD
                        stats.cumulDiff <= 0 ? (
                          <><TrendingUp size={13} /> Ahead by {Math.abs(stats.cumulDiff)}</>
                        ) : (
                          <><TrendingDown size={13} /> Behind by {stats.cumulDiff}</>
                        )
                      ) : (
                        // Increasing: cumulDiff = actual - target; positive = actual > target = AHEAD
                        stats.cumulDiff >= 0 ? (
                          <><TrendingUp size={13} /> Ahead by {stats.cumulDiff}</>
                        ) : (
                          <><TrendingDown size={13} /> Behind by {Math.abs(stats.cumulDiff)}</>
                        )
                      )}
                      {stats.gainActual !== null && (
                        <span className="inline-progress-detail">
                          {isDecreasing
                            ? `(reduced ${Math.abs(stats.gainActual)}, planned ${Math.abs(stats.gainTarget)})`
                            : `(added ${stats.gainActual >= 0 ? '+' : ''}${stats.gainActual}, planned +${stats.gainTarget})`
                          }
                        </span>
                      )}
                    </div>
                  )}
                </div>
              );
            })}

            {cycles.filter(c => c.year !== firstYear && (c.enabled || isActualSubmitted(c.year))).length === 0 && (
              <div className="no-active-years-message">
                <p>No years are currently activated for achieved value submissions. Contact your administrator.</p>
              </div>
            )}

            {/* Overall Progress Summary */}
            {overallProgress && (
              <div className={`overall-progress-summary ${overallProgress.diff >= 0 ? 'on-track' : 'behind'}`}>
                <div className="progress-summary-header">
                  <BarChart3 size={16} />
                  <span className="progress-summary-title">Overall Progress</span>
                </div>
                <div className="progress-summary-bar-container">
                  <div
                    className="progress-summary-bar-fill"
                    style={{ width: `${Math.min(overallProgress.percentage, 100)}%` }}
                  />
                </div>
                <div className="progress-summary-details">
                  <div className="progress-summary-stat">
                    <span className="progress-stat-label">Latest achieved ({overallProgress.latestActualYear})</span>
                    <span className="progress-stat-value">{overallProgress.latestActual}</span>
                  </div>
                  <div className="progress-summary-stat">
                    <span className="progress-stat-label">Overall target ({lastYear})</span>
                    <span className="progress-stat-value">{overallProgress.overallTarget}</span>
                  </div>
                  <div className="progress-summary-stat">
                    <span className="progress-stat-label">Progress toward target</span>
                    <span className="progress-stat-value">{overallProgress.percentage}%</span>
                  </div>
                  <div className={`progress-summary-stat highlight ${overallProgress.diff >= 0 ? 'surplus' : 'deficit'}`}>
                    <span className="progress-stat-label">{overallProgress.diff >= 0 ? 'Ahead of target' : 'Behind target'}</span>
                    <span className="progress-stat-value">
                      {overallProgress.diff >= 0 ? '+' : ''}{overallProgress.diff}
                    </span>
                  </div>
                </div>
                
              </div>
            )}
          </div>
        )}
      </div>

      {/* Footer Actions */}
      <div className="form-actions">
        {targetValuesLocked && cycles.filter(c => c.enabled).length > 0 && (
          <button
            type="button"
            className="btn btn-primary submit-all-btn"
            onClick={handleSubmitAllActuals}
            disabled={isSubmitting || Object.values(isEditing).some(e => e)}
          >
            {isSubmitting ? (
              <>
                <Loader2 className="animate-spin" size={16} />
                Submitting...
              </>
            ) : (
              'Submit All Achieved Values'
            )}
          </button>
        )}
        <button
          type="button"
          className="btn btn-secondary collapse-btn"
          onClick={onCollapse}
          disabled={isSubmitting}
        >
          <ChevronUp size={16} />
          Collapse
        </button>
      </div>
    </div>
  );
};

export default ExpandableParameterForm;
