import React, { useState, useEffect } from 'react';
import { facultyService } from '../../../services/facultyService';
import { Faculty } from '../../../types';
import { toast } from 'react-hot-toast';
import FacultyModal from '../../../components/faculty-modal/FacultyModal';
import './Faculties.css';

const Faculties: React.FC = () => {
  // State matching Angular component exactly
  const [pageSize] = useState<number>(100);
  const [page, setPage] = useState<number>(1);
  const [search] = useState<string>('');
  const [faculties, setFaculties] = useState<Faculty[]>([]);
  const [first, setFirst] = useState<number>(0);
  const [rows] = useState<number>(10);
  const [totalRecords, setTotalRecords] = useState<number>(0);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [isLoadingArr, setIsLoadingArr] = useState<{ [id: string]: boolean }>({});
  const [showModal, setShowModal] = useState<boolean>(false);
  const [selectedFaculty, setSelectedFaculty] = useState<Faculty | null>(null);

  useEffect(() => {
    getAllFaculties();
  }, []);

  const getAllFaculties = async () => {
    setIsLoading(true);
    try {
      const parameters = {
        page,
        pageSize,
        search,
      };
      
      const response = await facultyService.getFaculties(parameters.page, parameters.pageSize, parameters.search);
      setFaculties(response.Data || []);
      setTotalRecords(response.TotalCount || 0);
    } catch (error) {
      console.error('Error loading faculties:', error);
      toast.error('Failed to load faculties');
    } finally {
      setIsLoading(false);
    }
  };

  const editMethod = (faculty: Faculty) => {
    setSelectedFaculty(faculty);
    setShowModal(true);
  };

  const deleteMethod = async (id: string) => {
    // Show confirmation dialog
    const confirmed = window.confirm(
      "You won't be able to revert this! This will delete all data related to this Faculty!"
    );
    
    if (!confirmed) return;

    setIsLoadingArr(prev => ({ ...prev, [id]: true }));
    
    try {
      await facultyService.deleteFaculty(id);
      toast.success('Faculty Deleted Successfully');
      getAllFaculties();
    } catch (error) {
      toast.error('Failed to delete faculty');
    } finally {
      setIsLoadingArr(prev => ({ ...prev, [id]: false }));
    }
  };

  const pageChange = (event: { first: number; rows: number; page: number }) => {
    setFirst(event.first);
    setPage(event.page);
    getAllFaculties();
  };

  const openModal = (faculty: Faculty | null = null) => {
    setSelectedFaculty(faculty);
    setShowModal(true);
  };

  const closeModal = () => {
    setShowModal(false);
    setSelectedFaculty(null);
  };

  const handleSave = () => {
    // Refresh data and close modal
    getAllFaculties();
    closeModal();
  };

  return (
    <div className="faculties-page">
      <h2>Faculty List</h2>
      
      {/* PrimeNG p-table equivalent */}
      <div className="p-datatable p-component">
        <div className="p-datatable-wrapper">
          <table className="p-datatable-table">
            <thead className="p-datatable-thead">
              <tr>
                <th style={{ width: '10%' }}>S. No.</th>
                <th style={{ width: '30%' }}>Faculty Name</th>
                <th style={{ width: '30%' }}>Faculty Code</th>
                <th style={{ width: '30%' }}>Action</th>
              </tr>
            </thead>
            <tbody className="p-datatable-tbody">
              {isLoading ? (
                <tr>
                  <td colSpan={4} className="text-center p-4">
                    <div className="spinner">
                      <div className="loading-spinner"></div>
                    </div>
                  </td>
                </tr>
              ) : faculties.length === 0 ? (
                <tr>
                  <td colSpan={4} className="text-center p-4">
                    No faculties found
                  </td>
                </tr>
              ) : (
                faculties.map((faculty, index) => (
                  <tr key={faculty.id || faculty._id}>
                    <td>{first + index + 1}</td>
                    <td>{faculty.name}</td>
                    <td>{faculty.facultyCode}</td>
                    <td>
                      <div className="action-buttons">
                        <button
                          className="action-btn edit-btn"
                          onClick={() => editMethod(faculty)}
                          title="Edit"
                        >
                          <img
                            src="/assets/icons/ic--round-edit.svg"
                            alt="edit-icon"
                          />
                        </button>
                        <button
                          className="action-btn delete-btn"
                          onClick={() => deleteMethod(faculty.id)}
                          title="Delete"
                          disabled={isLoadingArr[faculty.id]}
                        >
                          {isLoadingArr[faculty.id] ? (
                            <div className="spinner">
                              <div className="loading-spinner small"></div>
                            </div>
                          ) : (
                            <img
                              src="/assets/icons/ep--delete-filled.svg"
                              alt="delete-icon"
                            />
                          )}
                        </button>
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* PrimeNG p-paginator equivalent */}
      <div className="p-paginator p-component p-paginator-bottom">
        <span className="p-paginator-current">
          Showing {totalRecords} of {totalRecords}
        </span>
      </div>

      {/* Add Button - PrimeNG floating action button */}
      <button
        className="p-button p-button-rounded p-button-icon-only p-button-fab"
        onClick={() => openModal()}
        title="Add Faculty"
      >
        <span className="pi pi-plus"></span>
      </button>

      {/* Faculty Modal for Create/Edit */}
      <FacultyModal
        faculty={selectedFaculty}
        isVisible={showModal}
        onClose={closeModal}
        onSave={handleSave}
      />
    </div>
  );
};

export default Faculties;