import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Eye, EyeOff, Loader2 } from 'lucide-react';
import { useAuth } from '../../hooks/useAuth';
import { toast } from 'react-hot-toast';
import { Button } from '../../components/ui/button';
import { Input } from '../../components/ui/input';
import { Checkbox } from '../../components/ui/checkbox';

interface LoginForm {
  username: string;
  password: string;
  rememberMe: boolean;
}

const Login: React.FC = () => {
  const navigate = useNavigate();
  const { login, isLoading } = useAuth();
  const [mounted, setMounted] = useState(false);
  
  const [formData, setFormData] = useState<LoginForm>({
    username: '',
    password: '',
    rememberMe: false
  });
  
  const [passwordVisible, setPasswordVisible] = useState(false);

  useEffect(() => {
    const timer = setTimeout(() => setMounted(true), 50);
    return () => clearTimeout(timer);
  }, []);

  const handleInputChange = (field: keyof LoginForm) => (e: React.ChangeEvent<HTMLInputElement>) => {
    setFormData(prev => ({
      ...prev,
      [field]: field === 'rememberMe' ? e.target.checked : e.target.value
    }));
  };

  const onSubmitLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    
    if (!formData.username || !formData.password) {
      toast.error('Please fill in all fields');
      return;
    }

    try {
      const response = await login({
        Username: formData.username,
        Password: formData.password
      });

      if (response.token) {
        localStorage.setItem('token', response.token);
        localStorage.setItem('userRole', response.role[0]);
        localStorage.setItem('tokenExpiration', response.expiration);
        localStorage.setItem('username', formData.username);
        if (response.fullName) localStorage.setItem('fullName', response.fullName);
        if (response.department) localStorage.setItem('department', response.department);
        
        toast.success('Login successful!');
        
        const adminPanelRoles = ['Admin', 'VC', 'PVC', 'Dean'];
        const qecUsers = new Set(['dirqec@neduet.edu.pk', 'testacch']);
        const shouldGoToAdmin = response.role?.some((r: string) => adminPanelRoles.includes(r)) || qecUsers.has(formData.username);
        navigate(shouldGoToAdmin ? '/admin' : '/dashboard');
      }
    } catch (error: any) {
      toast.error(error.message || 'Login failed');
    }
  };

  return (
    <div className="h-screen flex overflow-hidden">
      {/* Left — Login Form (35%) */}
      <div className="w-full lg:w-[35%] bg-white flex flex-col items-center justify-center px-8">
        <div
          className="w-full max-w-[420px] transition-all duration-700 ease-out"
          style={{
            opacity: mounted ? 1 : 0,
            transform: mounted ? 'translateX(0)' : 'translateX(-30px)',
          }}
        >
          {/* Logo + Branding */}
          <div className="text-center mb-8">
            <img
              src={require('../../assets/ned-logo.png')}
              alt="NED University Logo"
              className="h-[72px] w-[72px] mx-auto mb-3"
            />
            <h1 className="text-[1.2rem] font-bold text-gray-900 leading-snug">
              NED University Of Engineering &amp; Technology
            </h1>
            <div className="w-12 h-0.5 bg-gray-200 mx-auto my-3" />
            <p className="text-[13px] text-gray-400 tracking-widest uppercase">Strategic Management Portal</p>
          </div>

          {/* Form */}
          <form onSubmit={onSubmitLogin} className="space-y-5">
            <div
              className="transition-all duration-500 ease-out"
              style={{ opacity: mounted ? 1 : 0, transform: mounted ? 'translateY(0)' : 'translateY(12px)', transitionDelay: '200ms' }}
            >
              <label htmlFor="username" className="block text-sm font-medium text-gray-700 mb-1.5">
                Username
              </label>
              <Input
                id="username"
                type="text"
                placeholder="Enter your username"
                value={formData.username}
                onChange={handleInputChange('username')}
                className="w-full h-11"
                required
              />
            </div>

            <div
              className="transition-all duration-500 ease-out"
              style={{ opacity: mounted ? 1 : 0, transform: mounted ? 'translateY(0)' : 'translateY(12px)', transitionDelay: '350ms' }}
            >
              <label htmlFor="password1" className="block text-sm font-medium text-gray-700 mb-1.5">
                Password
              </label>
              <div className="relative">
                <Input
                  id="password1"
                  type={passwordVisible ? 'text' : 'password'}
                  placeholder="Enter your password"
                  value={formData.password}
                  onChange={handleInputChange('password')}
                  className="w-full pr-10 h-11"
                  required
                />
                <button
                  type="button"
                  className="absolute inset-y-0 right-0 pr-3 flex items-center"
                  onClick={() => setPasswordVisible(!passwordVisible)}
                  aria-label={passwordVisible ? 'Hide password' : 'Show password'}
                >
                  {passwordVisible ? <EyeOff className="h-4 w-4 text-gray-400" /> : <Eye className="h-4 w-4 text-gray-400" />}
                </button>
              </div>
            </div>

            <div
              className="flex items-center space-x-2 transition-all duration-500 ease-out"
              style={{ opacity: mounted ? 1 : 0, transform: mounted ? 'translateY(0)' : 'translateY(12px)', transitionDelay: '500ms' }}
            >
              <Checkbox
                id="rememberme1"
                checked={formData.rememberMe}
                onCheckedChange={(checked) => 
                  setFormData(prev => ({ ...prev, rememberMe: !!checked }))
                }
              />
              <label htmlFor="rememberme1" className="text-sm text-gray-600">
                Remember me
              </label>
            </div>

            <div
              className="transition-all duration-500 ease-out"
              style={{ opacity: mounted ? 1 : 0, transform: mounted ? 'translateY(0)' : 'translateY(12px)', transitionDelay: '600ms' }}
            >
              <Button
                type="submit"
                className="w-full h-11 text-sm font-medium"
                disabled={isLoading}
              >
                {isLoading ? (
                  <>
                    <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                    Signing in...
                  </>
                ) : (
                  'Sign In'
                )}
              </Button>
            </div>
          </form>
        </div>
      </div>

      {/* Right — Strategic Diagram (65%) */}
      <div className="hidden lg:flex w-[65%] h-screen items-center justify-center bg-white px-8 py-6">
        <img
          src={require('../../assets/strategic-diagram.jpg')}
          alt="NED University Strategic Framework"
          className="h-full w-auto object-contain rounded-2xl shadow-lg ring-1 ring-gray-100 transition-all duration-1000 ease-out"
          style={{
            opacity: mounted ? 1 : 0,
            transform: mounted ? 'translateX(0) scale(1)' : 'translateX(40px) scale(0.97)',
          }}
        />
      </div>
    </div>
  );
};

export default Login;
