import React, { useState, useEffect } from 'react';
import { createPortal } from 'react-dom';
import { X, ChevronDown } from 'lucide-react';
import { parameterService } from '../../services/parameterService';
import { cycleService } from '../../services/cycleService';
import { Parameter, ParameterFormData, Category, UserGroup } from '../../types';
import { Cycle } from '../../types/cycle.types';
import { toast } from 'react-hot-toast';
import MultiSelectDropdown from '../ui/multi-select-dropdown';
import './ParameterModal.css';

interface ParameterModalProps {
  parameter: Parameter | null;
  categories: Category[];
  cycles: Array<{id: string, name: string}>;
  parameterTypes: string[];
  userGroups: UserGroup[]; // ➕ NEW: User groups for access control
  isVisible: boolean;
  onClose: () => void;
  onSave: () => void;
}

const ParameterModal: React.FC<ParameterModalProps> = ({
  parameter,
  categories,
  cycles,
  parameterTypes,
  userGroups, // ➕ NEW: User groups prop
  isVisible,
  onClose,
  onSave
}) => {
  const [formData, setFormData] = useState<ParameterFormData>({
    name: '',
    description: '',
    category: '',
    cycle: '',
    maxValue: 100,
    parameterType: 'Numeric',
    sortOrder: 0,
    isActive: true,
    // ➕ NEW: Group access fields
    accessibleToGroups: ['Academic Departments'], // Default to Academic Departments
    restrictedAccess: true // New parameters are restricted by default
  });
  const [isLoading, setIsLoading] = useState(false);
  const [errors, setErrors] = useState<{ [key: string]: string }>({});
  const [dropdownStates, setDropdownStates] = useState({
    category: false,
    cycle: false,
    parameterType: false
  });

  // State for active cycle
  const [activeCycle, setActiveCycle] = useState<Cycle | null>(null);

  // Fetch active cycle when modal opens
  useEffect(() => {
    if (isVisible) {
      loadActiveCycle();
    }
  }, [isVisible]);

  const loadActiveCycle = async () => {
    try {
      const cycle = await cycleService.getActiveCycle(true);
      if (cycle) {
        setActiveCycle(cycle);
        console.log('✅ Active cycle loaded:', cycle.cycleName);
        console.log('📅 Activated years:', cycle.activatedYears);
      } else {
        setActiveCycle(null);
        toast.error('No active cycle found. Please activate a cycle first.');
      }
    } catch (error) {
      console.error('Error loading active cycle:', error);
      toast.error('Failed to load active cycle');
    }
  };

  useEffect(() => {
    if (isVisible) {
      if (parameter) {
        // Edit mode - populate form with existing data
        // Handle both 'name' and 'parameterName' fields from backend
        const paramName = (parameter as any).parameterName || parameter.name || '';

        setFormData({
          name: paramName,
          description: parameter.description || '',
          category: parameter.category,
          cycle: typeof parameter.cycle === 'object' && parameter.cycle?.name ? parameter.cycle.name : parameter.cycle || '',
          maxValue: parameter.maxValue,
          isDecreasing: (parameter as any).isDecreasing === true,
          parameterType: parameter.parameterType,
          sortOrder: (parameter as any).sortOrder || 0,
          isActive: (parameter as any).isActive !== undefined ? (parameter as any).isActive : true,
          // ➕ NEW: Handle existing parameter group access
          accessibleToGroups: (parameter as any).accessibleToGroups || ['Academic Departments'],
          restrictedAccess: (parameter as any).restrictedAccess !== undefined ? (parameter as any).restrictedAccess : false
        });
      } else {
        // Add mode - reset form
        setFormData({
          name: '',
          description: '',
          category: '',
          cycle: '',
          maxValue: 100,
          isDecreasing: false,
          parameterType: 'Numeric',
          sortOrder: 0,
          isActive: true,
          // ➕ NEW: Default group access for new parameters
          accessibleToGroups: ['Academic Departments'], // Default to Academic Departments
          restrictedAccess: true // New parameters are restricted by default
        });
      }
      setErrors({});
      setDropdownStates({ category: false, cycle: false, parameterType: false });
    }
  }, [parameter, isVisible]);

  const validateForm = (): boolean => {
    const newErrors: { [key: string]: string } = {};

    if (!formData.name.trim()) {
      newErrors.name = 'Parameter name is required';
    }

    if (!formData.category) {
      newErrors.category = 'Pillar selection is required';
    }

    if (!activeCycle) {
      newErrors.cycle = 'No active cycle available. Please activate a cycle first.';
    }

    if (!formData.parameterType) {
      newErrors.parameterType = 'Parameter type selection is required';
    }

    if (formData.maxValue <= 0) {
      newErrors.maxValue = 'Max value must be greater than 0';
    }


    // ➕ NEW: Validate group access control
    if (!formData.accessibleToGroups || formData.accessibleToGroups.length === 0) {
      newErrors.accessibleToGroups = 'At least one group must be selected';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleInputChange = (field: keyof ParameterFormData) => (
    e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>
  ) => {
    let value: any = e.target.value;
    
    // Handle numeric fields
    if (field === 'maxValue' || field === 'sortOrder') {
      const parsed = field === 'maxValue' ? Number(e.target.value) : parseInt(e.target.value);
      value = isNaN(parsed) ? 0 : parsed;
    }
    
    setFormData(prev => ({
      ...prev,
      [field]: value
    }));
    
    // Clear error when user starts typing
    if (errors[field]) {
      setErrors(prev => ({
        ...prev,
        [field]: ''
      }));
    }
  };

  const handleDropdownToggle = (dropdown: keyof typeof dropdownStates) => {
    if (isLoading) return;
    setDropdownStates(prev => ({
      ...prev,
      [dropdown]: !prev[dropdown]
    }));
  };

  const handleDropdownSelect = (field: keyof ParameterFormData, value: string, cycleId?: string) => {
    if (field === 'cycle' && cycleId) {
      // For cycles, store both display name and ID
      setFormData(prev => ({
        ...prev,
        cycle: value,      // Display name
        cycleId: cycleId   // ObjectId for backend
      }));
    } else {
      setFormData(prev => ({
        ...prev,
        [field]: value
      }));
    }
    
    setDropdownStates(prev => ({
      ...prev,
      [field]: false
    }));
    
    // Clear error
    if (errors[field]) {
      setErrors(prev => ({
        ...prev,
        [field]: ''
      }));
    }
  };

  const getSelectedValue = (field: keyof ParameterFormData): string => {
    const value = formData[field] as string;

    if (field === 'category') {
      if (!value) return 'Select Pillar';
      // Categories are stored by name, not ID in parameters
      return value;
    } else if (field === 'cycle') {
      return value || 'Select Cycle';
    } else if (field === 'parameterType') {
      return value || 'Select Parameter Type';
    }
    return value;
  };

  const getParameterTypeDescription = (type: string): string => {
    switch (type) {
      case 'Numeric': return 'Whole numbers (e.g., 1, 2, 3)';
      case 'Text': return 'Text or descriptive values';
      case 'Percentage': return 'Percentage values (0-100%)';
      case 'Boolean': return 'Yes/No or True/False values';
      default: return '';
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!validateForm()) {
      return;
    }

    // Extra validation for debugging
    if (!formData.name || formData.name.trim() === '') {
      toast.error('Parameter name is required');
      return;
    }

    if (!activeCycle) {
      toast.error('No active cycle available');
      return;
    }

    setIsLoading(true);

    try {
      // Build backend data carefully
      const cycleId = activeCycle._id || activeCycle.id;

      const backendData: any = {
        parameterName: formData.name.trim(),
        description: formData.description || '',
        category: formData.category,
        cycle: cycleId,
        parameterType: formData.parameterType,
        maxValue: formData.maxValue,
        isDecreasing: formData.isDecreasing === true,
        sortOrder: formData.sortOrder,
        isActive: formData.isActive,
        accessibleToGroups: formData.accessibleToGroups || ['Academic Departments'],
        restrictedAccess: formData.restrictedAccess !== undefined ? formData.restrictedAccess : true
      };

      console.log('🐛 DEBUG - Form Data:', formData);
      console.log('🐛 DEBUG - Active cycle:', activeCycle);
      console.log('🐛 DEBUG - Cycle ID:', cycleId);
      console.log('🐛 DEBUG - Backend data to send:', JSON.stringify(backendData, null, 2));

      if (parameter) {
        // Edit existing parameter - use _id if id is not available
        const parameterId = parameter.id || parameter._id;
        if (!parameterId) {
          toast.error('Parameter ID is missing');
          return;
        }
        await parameterService.updateParameter(parameterId, backendData as any);
        toast.success('Parameter updated successfully!');
      } else {
        // Create new parameter
        await parameterService.createParameter(backendData as any);
        toast.success('Parameter created successfully!');
      }
      
      onSave(); // Refresh parent data and close modal
    } catch (error: any) {
      toast.error(error.message || 'Operation failed');
    } finally {
      setIsLoading(false);
    }
  };

  const handleClose = () => {
    if (!isLoading) {
      setDropdownStates({ category: false, cycle: false, parameterType: false });
      onClose();
    }
  };

  const handleBackdropClick = () => {
    // Close dropdowns first, then modal
    const hasOpenDropdown = Object.values(dropdownStates).some(Boolean);
    if (hasOpenDropdown) {
      setDropdownStates({ category: false, cycle: false, parameterType: false });
    } else {
      handleClose();
    }
  };

  // Add body scroll lock
  useEffect(() => {
    if (isVisible) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = 'unset';
    }
    
    return () => {
      document.body.style.overflow = 'unset';
    };
  }, [isVisible]);

  if (!isVisible) return null;

  return createPortal(
    <div className="p-dialog-mask p-component-overlay p-component-overlay-enter" onClick={handleBackdropClick}>
        <div className="p-dialog p-component p-dialog-center parameter-modal" onClick={(e) => e.stopPropagation()}>
          <div className="p-dialog-content">
            {/* Modal Header */}
            <div className="p-dialog-header">
              <span className="p-dialog-title">
                {parameter ? 'Edit Parameter' : 'Add Parameter'}
              </span>
              <div className="p-dialog-header-icons">
                <button
                  className="p-dialog-header-icon p-dialog-header-close"
                  type="button"
                  onClick={handleClose}
                  disabled={isLoading}
                >
                  <X className="h-4 w-4" />
                </button>
              </div>
            </div>

            {/* Modal Body */}
            <form onSubmit={handleSubmit} className="parameter-form">
              <div className="p-fluid">
                {/* First Row - Parameter Name */}
                <div className="form-row">
                  <div className="field col-12">
                    <label htmlFor="parameterName" className="required-field">
                      Parameter Name
                    </label>
                    <input
                      id="parameterName"
                      type="text"
                      placeholder="Enter parameter name"
                      value={formData.name}
                      onChange={handleInputChange('name')}
                      className={`p-inputtext p-component ${errors.name ? 'p-invalid' : ''}`}
                      disabled={isLoading}
                      required
                    />
                    {errors.name && (
                      <small className="p-error">{errors.name}</small>
                    )}
                  </div>
                </div>

                {/* Second Row - Description */}
                <div className="form-row">
                  <div className="field col-12">
                    <label htmlFor="parameterDescription">
                      Parameter Description
                    </label>
                    <textarea
                      id="parameterDescription"
                      placeholder="Enter parameter description (optional)"
                      value={formData.description}
                      onChange={handleInputChange('description')}
                      className="p-inputtext p-component"
                      rows={3}
                      disabled={isLoading}
                    />
                  </div>
                </div>

                {/* Third Row - Category and Cycle */}
                <div className="form-row">
                  <div className="field col-6">
                    <label className="required-field">Pillar</label>
                    <div className={`p-dropdown p-component ${errors.category ? 'p-invalid' : ''}`}>
                      <div
                        className="p-dropdown-label-container"
                        onClick={() => handleDropdownToggle('category')}
                      >
                        <span className="p-dropdown-label">
                          {getSelectedValue('category')}
                        </span>
                        <div className="p-dropdown-trigger">
                          <ChevronDown className={`p-dropdown-trigger-icon ${dropdownStates.category ? 'rotated' : ''}`} />
                        </div>
                      </div>

                      {dropdownStates.category && (
                        <div className="p-dropdown-panel">
                          <div className="p-dropdown-items-wrapper">
                            <ul className="p-dropdown-items">
                              {categories.length === 0 ? (
                                <li className="p-dropdown-item p-dropdown-empty-message">
                                  No pillars available
                                </li>
                              ) : (
                                categories.map((category) => (
                                  <li
                                    key={category.id}
                                    className={`p-dropdown-item ${formData.category === category.name ? 'p-highlight' : ''}`}
                                    onClick={() => handleDropdownSelect('category', category.name)}
                                  >
                                    {category.name}
                                  </li>
                                ))
                              )}
                            </ul>
                          </div>
                        </div>
                      )}
                    </div>
                    {errors.category && (
                      <small className="p-error">{errors.category}</small>
                    )}
                  </div>

                  <div className="field col-6">
                    <label>Active Cycle</label>
                    <div className="cycle-info-display">
                      {activeCycle ? (
                        <>
                          <div className="cycle-name">{activeCycle.cycleName}</div>
                          <div className="cycle-details">
                            {activeCycle.activatedYears && activeCycle.activatedYears.length > 0 ? (
                              <span className="activated-years">
                                Activated Years: {activeCycle.activatedYears.join(', ')}
                              </span>
                            ) : (
                              <span className="no-years-warning">
                                No years activated yet
                              </span>
                            )}
                          </div>
                        </>
                      ) : (
                        <span className="no-cycle-warning">No active cycle found</span>
                      )}
                    </div>
                    {errors.cycle && (
                      <small className="p-error">{errors.cycle}</small>
                    )}
                  </div>
                </div>

                {/* Fourth Row - Parameter Type and Max Value */}
                <div className="form-row">
                  <div className="field col-8">
                    <label className="required-field">Parameter Type</label>
                    <div className={`p-dropdown p-component ${errors.parameterType ? 'p-invalid' : ''}`}>
                      <div 
                        className="p-dropdown-label-container"
                        onClick={() => handleDropdownToggle('parameterType')}
                      >
                        <span className="p-dropdown-label">
                          {getSelectedValue('parameterType')}
                        </span>
                        <div className="p-dropdown-trigger">
                          <ChevronDown className={`p-dropdown-trigger-icon ${dropdownStates.parameterType ? 'rotated' : ''}`} />
                        </div>
                      </div>
                      
                      {dropdownStates.parameterType && (
                        <div className="p-dropdown-panel">
                          <div className="p-dropdown-items-wrapper">
                            <ul className="p-dropdown-items">
                              {parameterTypes.map((type) => (
                                <li 
                                  key={type}
                                  className={`p-dropdown-item ${formData.parameterType === type ? 'p-highlight' : ''}`}
                                  onClick={() => handleDropdownSelect('parameterType', type)}
                                >
                                  <div className="parameter-type-option">
                                    <span className="type-name">{type}</span>
                                    <span className="type-description">{getParameterTypeDescription(type)}</span>
                                  </div>
                                </li>
                              ))}
                            </ul>
                          </div>
                        </div>
                      )}
                    </div>
                    {errors.parameterType && (
                      <small className="p-error">{errors.parameterType}</small>
                    )}
                  </div>

                  <div className="field col-4">
                    <label htmlFor="maxValue" className="required-field">
                      Max Value
                    </label>
                    <input
                      id="maxValue"
                      type="text"
                      inputMode="numeric"
                      pattern="[0-9]*"
                      placeholder="100"
                      value={formData.maxValue}
                      onChange={handleInputChange('maxValue')}
                      className={`p-inputtext p-component ${errors.maxValue ? 'p-invalid' : ''}`}
                      disabled={isLoading}
                      required
                    />
                    {errors.maxValue && (
                      <small className="p-error">{errors.maxValue}</small>
                    )}
                    <small className="field-help">Maximum allowed value for this parameter</small>
                  </div>
                </div>

                {/* Fifth Row - Sort Order and Active Status */}
                <div className="form-row">
                  <div className="field col-6">
                    <label htmlFor="sortOrder" className="required-field">
                      Sort Order
                    </label>
                    <input
                      id="sortOrder"
                      type="number"
                      placeholder="0"
                      value={formData.sortOrder}
                      onChange={handleInputChange('sortOrder')}
                      className={`p-inputtext p-component ${errors.sortOrder ? 'p-invalid' : ''}`}
                      disabled={isLoading}
                      min="0"
                      max="1000"
                      step="1"
                      required
                    />
                    {errors.sortOrder && (
                      <small className="p-error">{errors.sortOrder}</small>
                    )}
                    <small className="field-help">Display order (0 = first)</small>
                  </div>

                  <div className="field col-6">
                    <label htmlFor="isActive">
                      Status
                    </label>
                    <div className="p-inputswitch p-component">
                      <div className={`p-inputswitch-slider ${formData.isActive ? 'p-inputswitch-checked' : ''}`}>
                        <input
                          id="isActive"
                          type="checkbox"
                          checked={formData.isActive}
                          onChange={(e) => setFormData(prev => ({ ...prev, isActive: e.target.checked }))}
                          disabled={isLoading}
                        />
                        <span className="p-inputswitch-slider-handle"></span>
                      </div>
                    </div>
                    <small className="field-help">
                      {formData.isActive ? 'Parameter is active' : 'Parameter is inactive'}
                    </small>
                  </div>
                </div>

                {/* ➕ NEW: Sixth Row - Value Direction Toggle */}
                <div className="form-row">
                  <div className="field col-12">
                    <label htmlFor="isDecreasing">
                      Value Direction
                    </label>
                    <div className="p-inputswitch p-component">
                      <div className={`p-inputswitch-slider ${formData.isDecreasing ? 'p-inputswitch-checked' : ''}`}>
                        <input
                          id="isDecreasing"
                          type="checkbox"
                          checked={formData.isDecreasing === true}
                          onChange={(e) => setFormData(prev => ({ ...prev, isDecreasing: e.target.checked }))}
                          disabled={isLoading}
                        />
                        <span className="p-inputswitch-slider-handle"></span>
                      </div>
                    </div>
                    <small className="field-help">
                      {formData.isDecreasing
                        ? '📉 Values decrease over time — lower is better (e.g. dropout rate, complaints, waste)'
                        : '📈 Values increase over time — higher is better (default for most parameters)'}
                    </small>
                  </div>
                </div>

                {/* ➕ NEW: Sixth Row - Group Access Control */}
                <div className="form-row">
                  <div className="field col-12">
                    <label className="required-field">
                      Group Access Control
                    </label>
                    <MultiSelectDropdown
                      options={userGroups}
                      value={formData.accessibleToGroups || []}
                      onChange={(selectedGroups) => {
                        setFormData(prev => ({
                          ...prev,
                          accessibleToGroups: selectedGroups,
                          restrictedAccess: selectedGroups.length > 0
                        }));
                        // Clear error when user selects groups
                        if (errors.accessibleToGroups) {
                          setErrors(prev => ({
                            ...prev,
                            accessibleToGroups: ''
                          }));
                        }
                      }}
                      placeholder="Select groups who can access this parameter..."
                      className={errors.accessibleToGroups ? 'p-invalid' : ''}
                      disabled={isLoading}
                      required={true}
                      error={errors.accessibleToGroups}
                    />
                    {errors.accessibleToGroups && (
                      <small className="p-error">{errors.accessibleToGroups}</small>
                    )}
                    <small className="field-help">
                      Select which groups can see and use this parameter. Admin users always see all parameters.
                    </small>
                  </div>
                </div>
              </div>

              {/* Modal Footer */}
              <div className="p-dialog-footer">
                <button
                  type="button"
                  className="p-button p-component p-button-secondary"
                  onClick={handleClose}
                  disabled={isLoading}
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  className="p-button p-component p-button-primary"
                  disabled={isLoading}
                >
                  {isLoading ? (
                    <span className="p-button-loading-icon pi pi-spinner pi-spin"></span>
                  ) : null}
                  {isLoading 
                    ? 'Saving...' 
                    : (parameter ? 'Update Parameter' : 'Create Parameter')
                  }
                </button>
              </div>
            </form>
          </div>
        </div>
      </div>,
    document.body
  );
};

export default ParameterModal;