import { authService } from './authService';

// ─── Types ────────────────────────────────────────────────────────────────────

export interface CycleMeta {
  id: number;
  name: string;
  cycleName: string;
  yearRange: string;
  cycleYears: number[];
  activatedYears: number[];
  currentActiveYear: number;
  targetYear: number;
  selectedYear: number;
}

export interface UniversityPulse {
  total: number;
  uniqueParams: number;
  exceeding: number;
  onTrack: number;
  behind: number;
  critical: number;
  pending: number;
  noTarget: number;
  withActuals: number;
  // Department-level headline counts
  totalDepts: number;
  deptsOnTrack: number;
  deptsStruggling: number;
  deptsPending: number;
  deptsNoData: number;
}

export type RagStatus = 'green' | 'amber' | 'red' | 'pending' | 'no_data';
export type ParamStatus = 'exceeding' | 'on_track' | 'behind' | 'critical' | 'pending' | 'no_target' | 'text';

export interface PillarScore {
  categoryId: number;
  categoryName: string;
  shortName: string;
  total: number;
  uniqueParams: number;
  uniqueSubmissions: number;
  withActuals: number;
  // Department-level counts
  totalDepts: number;
  deptsOnTrack: number;
  deptsStruggling: number;
  deptsPending: number;
  deptsNoData: number;
  exceeding: number;
  onTrack: number;
  behind: number;
  critical: number;
  pending: number;
  noTarget: number;
  avgYearScore: number;
  avgJourneyPct: number;
  onTrackRate: number;
  ragStatus: RagStatus;
}

export interface YearTimelineEntry {
  year: number;
  label: string;
  isBaseline: boolean;
  isCurrentActive: boolean;
  isActivated: boolean;
  isFuture: boolean;
  isTargetYear: boolean;
  withTargets: number;
  withActuals: number;
  total: number;
  avgScore: number | null;
  completionPct: number;
}

export interface ScorecardData {
  cycle: CycleMeta;
  universityPulse: UniversityPulse;
  pillarScores: PillarScore[];
  yearTimeline: YearTimelineEntry[];
}

export interface YearlyDataPoint {
  year: number;
  target: number | null;
  actual: number | null;
  score: number | null;
  status: ParamStatus;
}

export interface ParameterRow {
  parameterId: number;
  parameterName: string;
  categoryId: number;
  categoryName: string;
  departmentId: number;
  departmentName: string;
  facultyId: number;
  facultyName: string;
  isDecreasing: boolean;
  parameterType: string;
  baseline: { year: number; value: number } | null;
  overallTarget: number | null;
  targetYearData: { year: number; projectedValue: number | null; actualValue: number | null };
  yearlyData: YearlyDataPoint[];
  yearScore: number | null;
  journeyPct: number | null;
  latestActual: number | null;
  latestActualYear: number | null;
  status: ParamStatus;
  targetValuesLocked: boolean;
}

export interface DeptLeagueRow {
  rank: number;
  departmentId: number;
  departmentName: string;
  deptCode?: string | null;
  facultyId: number;
  facultyName: string;
  total: number;
  exceeding: number;
  onTrack: number;
  behind: number;
  critical: number;
  pending: number;
  avgScore: number;
  avgJourneyPct: number;
  onTrackRate: number;
}

export interface DrillDownData {
  cycle: {
    id: number;
    name: string;
    selectedYear: number;
    targetYear: number;
    activatedYears: number[];
    cycleYears: number[];
  };
  parameterRows: ParameterRow[];
  deptLeague: DeptLeagueRow[];
  totalParams: number;
}

// ─── Service ──────────────────────────────────────────────────────────────────

class AnalyticsService {
  async getScorecard(cycleId?: number | string, year?: number | string): Promise<ScorecardData> {
    const params = new URLSearchParams();
    if (cycleId) params.append('cycleId', cycleId.toString());
    if (year)    params.append('year', year.toString());

    const res = await authService.axiosInstance.get(`/api/analytics/scorecard?${params.toString()}`);
    if (!res.data.success) throw new Error(res.data.message || 'Failed to load scorecard');
    return res.data.data as ScorecardData;
  }

  async getDrillDown(
    cycleId?: number | string,
    year?: number | string,
    categoryId?: number | string,
    deptId?: number | string,
  ): Promise<DrillDownData> {
    const params = new URLSearchParams();
    if (cycleId)    params.append('cycleId', cycleId.toString());
    if (year)       params.append('year', year.toString());
    if (categoryId) params.append('categoryId', categoryId.toString());
    if (deptId)     params.append('deptId', deptId.toString());

    const res = await authService.axiosInstance.get(`/api/analytics/drill?${params.toString()}`);
    if (!res.data.success) throw new Error(res.data.message || 'Failed to load drill-down');
    return res.data.data as DrillDownData;
  }
}

export const analyticsService = new AnalyticsService();
