import React, { useState, useMemo } from 'react';
import {
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer,
  Cell, RadarChart, Radar, PolarGrid, PolarAngleAxis as RechartsPolarAngleAxis, PolarRadiusAxis,
} from 'recharts';
import {
  faculties, pillarStatus, heatmapData, activeYear, cycleYears,
  departmentPerformance,
} from './mockData';

const PolarAngleAxis = RechartsPolarAngleAxis as any;

const completionColor = (pct: number) => {
  if (pct >= 85) return '#10b981';
  if (pct >= 60) return '#f59e0b';
  return '#ef4444';
};

const heatColor = (val: number) => {
  if (val === 0) return '#f3f4f6';
  if (val >= 85) return '#bbf7d0';
  if (val >= 70) return '#d9f99d';
  if (val >= 55) return '#fef08a';
  if (val >= 40) return '#fed7aa';
  return '#fecaca';
};
const heatTextColor = (val: number) => {
  if (val === 0) return '#9ca3af';
  if (val >= 70) return '#166534';
  if (val >= 55) return '#92400e';
  return '#991b1b';
};

const seededRandom = (seed: number) => {
  const x = Math.sin(seed * 9301 + 49297) * 49297;
  return x - Math.floor(x);
};

const DeptTooltip = ({ active, payload }: any) => {
  if (!active || !payload?.length) return null;
  const d = payload[0].payload;
  return (
    <div className="bg-white border border-gray-200 rounded-lg shadow-lg p-3 text-sm">
      <p className="font-semibold text-gray-900 mb-1">{d.name}</p>
      <p className="text-gray-600">{d.submitted} / {d.expected} submitted</p>
      <p className="text-gray-500 text-xs mt-1">{Math.round(d.submitted / d.expected * 100)}% complete</p>
    </div>
  );
};

const FacultyView: React.FC = () => {
  const [selectedFacultyId, setSelectedFacultyId] = useState(faculties[0].id);
  const [barChartYear, setBarChartYear] = useState<number | 'all'>('all');
  const [heatmapYear, setHeatmapYear] = useState<number>(activeYear);
  const faculty = faculties.find(f => f.id === selectedFacultyId)!;

  // Compute per-year department data for the bar chart
  const deptBarData = useMemo(() => {
    return faculty.departments.map(dept => {
      if (barChartYear === 'all') {
        return { ...dept, submitted: dept.totalSubmitted, expected: dept.totalExpected, pct: dept.completionPct };
      }
      const year = barChartYear as number;
      if (year > activeYear) {
        return { ...dept, submitted: 0, expected: dept.totalExpected, pct: 0 };
      }
      const scale = year === activeYear
        ? 0.6 + seededRandom(dept.id * 100 + year) * 0.35
        : 0.75 + seededRandom(dept.id * 100 + year) * 0.25;
      const submitted = Math.round(dept.totalExpected * (dept.completionPct / 100) * scale);
      return {
        ...dept,
        submitted,
        expected: dept.totalExpected,
        pct: Math.round(submitted / dept.totalExpected * 100),
      };
    }).sort((a, b) => a.pct - b.pct);
  }, [faculty, barChartYear]);

  const radarData = pillarStatus.map(pillar => {
    const cells = heatmapData.filter(h => h.facultyCode === faculty.code && h.pillarShort === pillar.shortName && h.year <= activeYear && h.value > 0);
    const avg = cells.length > 0 ? Math.round(cells.reduce((s, c) => s + c.value, 0) / cells.length) : 0;
    return { pillar: pillar.shortName, value: avg };
  });

  const pillarShorts = pillarStatus.map(p => p.shortName);
  const deptPillarData: Record<string, Record<string, number>> = {};
  faculty.departments.forEach(dept => {
    deptPillarData[dept.code] = {};
    pillarStatus.forEach(pillar => {
      const basePct = dept.completionPct;
      const pillarBias = pillar.completionRate;
      const seed = dept.id * 1000 + pillar.id * 10 + heatmapYear;
      const jitter = (seededRandom(seed) - 0.5) * 40;
      let val = Math.round(basePct * 0.45 + pillarBias * 0.35 + jitter);
      val = Math.max(0, Math.min(100, val));
      if (heatmapYear > activeYear) val = 0;
      deptPillarData[dept.code][pillar.shortName] = val;
    });
  });

  const pendingDepts = faculty.departments.filter(d => d.status !== 'complete');

  return (
    <div className="space-y-6">
      {/* Faculty Selector */}
      <div className="bg-white rounded-xl border border-gray-200 p-5">
        <div className="flex items-center justify-between flex-wrap gap-4">
          <div className="flex items-center gap-3">
            <select
              value={selectedFacultyId}
              onChange={e => setSelectedFacultyId(Number(e.target.value))}
              className="border border-gray-300 rounded-lg px-4 py-2 text-sm font-medium bg-white"
            >
              {faculties.map(f => (
                <option key={f.id} value={f.id}>{f.name} ({f.code})</option>
              ))}
            </select>
          </div>
          <div className="flex items-center gap-6">
            <div className="text-center">
              <div className="text-2xl font-bold" style={{ color: completionColor(faculty.completionPct) }}>
                {faculty.completionPct}%
              </div>
              <div className="text-xs text-gray-500">Data Collected</div>
            </div>
            <div className="text-center">
              <div className="text-2xl font-bold text-gray-900">{faculty.departments.length}</div>
              <div className="text-xs text-gray-500">Departments</div>
            </div>
            <div className="text-center">
              <div className="text-2xl font-bold text-emerald-600">{faculty.deptComplete}</div>
              <div className="text-xs text-gray-500">Fully Reported</div>
            </div>
            <div className="text-center">
              <div className="text-2xl font-bold text-amber-500">{faculty.deptPartial}</div>
              <div className="text-xs text-gray-500">In Progress</div>
            </div>
          </div>
        </div>
      </div>

      {/* Dept Bar Chart (HALF) + Radar (HALF) */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="bg-white rounded-xl border border-gray-200 p-6">
          <div className="flex items-center justify-between mb-4">
            <div>
              <h3 className="text-lg font-semibold text-gray-900">Department Submission Status</h3>
              <p className="text-sm text-gray-500 mt-0.5">Data collected per department</p>
            </div>
            <div className="flex items-center gap-1 bg-gray-100 rounded-lg p-0.5 shrink-0 ml-4">
              <button
                onClick={() => setBarChartYear('all')}
                className={`px-2.5 py-1 rounded-md text-xs font-medium transition-all ${
                  barChartYear === 'all' ? 'bg-white text-gray-900 shadow-sm' : 'text-gray-500 hover:text-gray-700'
                }`}
              >
                All Years
              </button>
              {cycleYears.map(y => (
                <button
                  key={y}
                  onClick={() => setBarChartYear(y)}
                  className={`px-2.5 py-1 rounded-md text-xs font-medium transition-all ${
                    barChartYear === y ? 'bg-white text-gray-900 shadow-sm' : 'text-gray-500 hover:text-gray-700'
                  } ${y === activeYear && barChartYear !== y ? 'text-blue-600' : ''}`}
                >
                  {y}
                </button>
              ))}
            </div>
          </div>
          <div style={{ height: Math.max(300, deptBarData.length * 44 + 40) }}>
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={deptBarData} layout="vertical" margin={{ left: 0, right: 30, top: 4, bottom: 4 }}>
                <CartesianGrid strokeDasharray="3 3" horizontal={false} stroke="#f0f0f0" />
                <XAxis type="number" domain={[0, 100]} tick={{ fontSize: 11 }} tickFormatter={v => `${v}%`} />
                <YAxis type="category" dataKey="code" width={50} tick={{ fontSize: 13, fontWeight: 600 }} interval={0} />
                <Tooltip content={<DeptTooltip />} cursor={{ fill: 'rgba(0,0,0,0.04)' }} />
                <Bar dataKey="pct" radius={[0, 6, 6, 0]} barSize={26}>
                  {deptBarData.map((entry, i) => (
                    <Cell key={i} fill={completionColor(entry.pct)} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white rounded-xl border border-gray-200 p-6">
          <h3 className="text-lg font-semibold text-gray-900 mb-1">Pillar Coverage</h3>
          <p className="text-sm text-gray-500 mb-3">Which pillars have the most/least data from this faculty</p>
          <div style={{ height: Math.max(360, deptBarData.length * 44 + 40 - 60) }}>
            <ResponsiveContainer width="100%" height="100%">
              <RadarChart cx="50%" cy="50%" outerRadius="70%" data={radarData}>
                <PolarGrid stroke="#cbd5e1" strokeWidth={1} />
                <PolarAngleAxis dataKey="pillar" tick={{ fontSize: 10, fill: '#374151' }} />
                <PolarRadiusAxis angle={30} domain={[0, 100]} tick={{ fontSize: 10 }} stroke="#94a3b8" />
                <Radar
                  name="Coverage"
                  dataKey="value"
                  stroke="#6366f1"
                  fill="#818cf8"
                  fillOpacity={0.35}
                  strokeWidth={2}
                />
              </RadarChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>

      {/* Department Performance Against Targets */}
      <div className="bg-white rounded-xl border border-gray-200 p-6">
        {(() => {
          const facultyDeptPerf = departmentPerformance.filter(d => d.facultyId === faculty.id);
          const totalExceeding = facultyDeptPerf.reduce((s, d) => s + d.breakdown.exceeding, 0);
          const totalMeeting = facultyDeptPerf.reduce((s, d) => s + d.breakdown.meeting, 0);
          const totalBelow = facultyDeptPerf.reduce((s, d) => s + d.breakdown.below, 0);
          const totalNoActual = facultyDeptPerf.reduce((s, d) => s + d.breakdown.noActualYet, 0);
          const totalNoTarget = facultyDeptPerf.reduce((s, d) => s + d.breakdown.noTargetYet, 0);
          const tracked = totalExceeding + totalMeeting + totalBelow;
          const facultyOnTrackPct = tracked > 0 ? Math.round((totalExceeding + totalMeeting) / tracked * 100) : 0;

          return (
            <>
              <div className="flex items-center justify-between mb-4">
                <div>
                  <h3 className="text-lg font-semibold text-gray-900">Department Performance Against Targets</h3>
                  <p className="text-sm text-gray-500 mt-0.5">Per parameter: is achieved value meeting projected target for {activeYear}?</p>
                </div>
                <div className="text-right">
                  <div className="text-2xl font-bold" style={{ color: completionColor(facultyOnTrackPct) }}>{facultyOnTrackPct}%</div>
                  <div className="text-xs text-gray-500">Parameters on track</div>
                </div>
              </div>

              <div className="grid grid-cols-2 sm:grid-cols-5 gap-3 mb-5">
                <div className="rounded-lg p-2.5 text-center" style={{ backgroundColor: '#ecfdf5' }}>
                  <div className="text-lg font-bold text-emerald-700">{totalExceeding}</div>
                  <div className="text-[11px] text-emerald-600">Exceeding Target</div>
                </div>
                <div className="rounded-lg p-2.5 text-center" style={{ backgroundColor: '#eff6ff' }}>
                  <div className="text-lg font-bold text-blue-700">{totalMeeting}</div>
                  <div className="text-[11px] text-blue-600">Meeting Target</div>
                </div>
                <div className="rounded-lg p-2.5 text-center" style={{ backgroundColor: '#fef2f2' }}>
                  <div className="text-lg font-bold text-red-700">{totalBelow}</div>
                  <div className="text-[11px] text-red-600">Below Target</div>
                </div>
                <div className="rounded-lg p-2.5 text-center" style={{ backgroundColor: '#fffbeb' }}>
                  <div className="text-lg font-bold text-amber-700">{totalNoActual}</div>
                  <div className="text-[11px] text-amber-600">Awaiting Achieved</div>
                </div>
                <div className="rounded-lg p-2.5 text-center bg-gray-50">
                  <div className="text-lg font-bold text-gray-500">{totalNoTarget}</div>
                  <div className="text-[11px] text-gray-400">Targets Not Set</div>
                </div>
              </div>

              {/* Per-department stacked bars */}
              <div className="space-y-2.5">
                {facultyDeptPerf.map(dept => {
                  const t = dept.breakdown.exceeding + dept.breakdown.meeting + dept.breakdown.below + dept.breakdown.noActualYet + dept.breakdown.noTargetYet;
                  if (t === 0) return null;
                  return (
                    <div key={dept.id}>
                      <div className="flex items-center justify-between mb-1">
                        <span className="text-xs font-medium text-gray-700">{dept.name}</span>
                        <span className="text-xs font-semibold" style={{ color: completionColor(dept.onTrackPct) }}>{dept.onTrackPct}% on track</span>
                      </div>
                      <div className="flex h-3 rounded-full overflow-hidden bg-gray-100">
                        {dept.breakdown.exceeding > 0 && (
                          <div style={{ width: `${(dept.breakdown.exceeding / t) * 100}%`, backgroundColor: '#10b981' }} title={`${dept.breakdown.exceeding} exceeding`} />
                        )}
                        {dept.breakdown.meeting > 0 && (
                          <div style={{ width: `${(dept.breakdown.meeting / t) * 100}%`, backgroundColor: '#3b82f6' }} title={`${dept.breakdown.meeting} meeting`} />
                        )}
                        {dept.breakdown.below > 0 && (
                          <div style={{ width: `${(dept.breakdown.below / t) * 100}%`, backgroundColor: '#ef4444' }} title={`${dept.breakdown.below} below`} />
                        )}
                        {dept.breakdown.noActualYet > 0 && (
                          <div style={{ width: `${(dept.breakdown.noActualYet / t) * 100}%`, backgroundColor: '#fbbf24' }} title={`${dept.breakdown.noActualYet} awaiting achieved values`} />
                        )}
                        {dept.breakdown.noTargetYet > 0 && (
                          <div style={{ width: `${(dept.breakdown.noTargetYet / t) * 100}%`, backgroundColor: '#e5e7eb' }} title={`${dept.breakdown.noTargetYet} no targets`} />
                        )}
                      </div>
                    </div>
                  );
                })}
              </div>
              <div className="flex items-center gap-5 mt-4 text-xs text-gray-500">
                <span className="flex items-center gap-1.5"><span className="w-2.5 h-2.5 rounded" style={{ backgroundColor: '#10b981' }} /> Exceeding</span>
                <span className="flex items-center gap-1.5"><span className="w-2.5 h-2.5 rounded" style={{ backgroundColor: '#3b82f6' }} /> Meeting</span>
                <span className="flex items-center gap-1.5"><span className="w-2.5 h-2.5 rounded" style={{ backgroundColor: '#ef4444' }} /> Below</span>
                <span className="flex items-center gap-1.5"><span className="w-2.5 h-2.5 rounded" style={{ backgroundColor: '#fbbf24' }} /> Awaiting Achieved</span>
                <span className="flex items-center gap-1.5"><span className="w-2.5 h-2.5 rounded" style={{ backgroundColor: '#e5e7eb' }} /> Targets Not Set</span>
              </div>
            </>
          );
        })()}
      </div>

      {/* Pending Submissions */}
      {pendingDepts.length > 0 && (
        <div className="bg-white rounded-xl border border-gray-200 p-6">
          <h3 className="text-lg font-semibold text-gray-900 mb-1">Pending Submissions</h3>
          <p className="text-sm text-gray-500 mb-5">Departments that haven't fully submitted yet</p>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {pendingDepts.sort((a, b) => a.completionPct - b.completionPct).map(dept => (
              <div key={dept.id} className="border border-gray-100 rounded-lg p-4">
                <div className="flex items-start justify-between gap-2 mb-2">
                  <span className="text-sm font-semibold text-gray-800 leading-tight">{dept.name}</span>
                  <span className="text-sm font-bold shrink-0" style={{ color: completionColor(dept.completionPct) }}>{dept.completionPct}%</span>
                </div>
                <div className="w-full bg-gray-100 rounded-full h-2.5 mb-2">
                  <div className="h-2.5 rounded-full" style={{ width: `${dept.completionPct}%`, backgroundColor: completionColor(dept.completionPct) }} />
                </div>
                <div className="text-xs text-gray-400">
                  {dept.totalSubmitted} / {dept.totalExpected} submitted
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Mini Heatmap: Dept × Pillar with year filter */}
      <div className="bg-white rounded-xl border border-gray-200 p-6">
        <div className="flex items-center justify-between mb-4">
          <div>
            <h3 className="text-lg font-semibold text-gray-900">Department × Pillar Breakdown</h3>
            <p className="text-sm text-gray-500">Data collection rates for each department across pillars</p>
          </div>
          <div className="flex items-center gap-1 bg-gray-100 rounded-lg p-0.5">
            {cycleYears.map(y => (
              <button
                key={y}
                onClick={() => setHeatmapYear(y)}
                className={`px-3 py-1.5 rounded-md text-xs font-medium transition-all ${
                  heatmapYear === y ? 'bg-white text-gray-900 shadow-sm' : 'text-gray-500 hover:text-gray-700'
                } ${y === activeYear && heatmapYear !== y ? 'text-blue-600' : ''}`}
              >
                {y}{y === activeYear ? ' *' : ''}
              </button>
            ))}
          </div>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-xs">
            <thead>
              <tr>
                <th className="text-left py-2 pr-2 font-medium text-gray-600 min-w-[70px]">Dept</th>
                {pillarShorts.map(p => (
                  <th key={p} className="text-center py-2 px-1 font-medium text-gray-600 min-w-[60px]">
                    <span className="block truncate max-w-[60px]" title={p}>{p.length > 10 ? p.slice(0, 8) + '..' : p}</span>
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {faculty.departments.map(dept => (
                <tr key={dept.code}>
                  <td className="py-1.5 pr-2 font-semibold text-gray-700">{dept.code}</td>
                  {pillarShorts.map(ps => {
                    const val = deptPillarData[dept.code]?.[ps] ?? 0;
                    return (
                      <td key={ps} className="py-1 px-0.5 text-center">
                        <div
                          className="rounded px-1 py-1.5 font-semibold text-[10px]"
                          style={{ backgroundColor: heatColor(val), color: heatTextColor(val) }}
                        >
                          {val > 0 ? `${val}%` : '—'}
                        </div>
                      </td>
                    );
                  })}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
        <div className="flex items-center gap-4 mt-3 text-xs text-gray-500">
          <span className="flex items-center gap-1"><span className="w-3 h-3 rounded" style={{ backgroundColor: '#bbf7d0' }} /> 85%+</span>
          <span className="flex items-center gap-1"><span className="w-3 h-3 rounded" style={{ backgroundColor: '#d9f99d' }} /> 70-84%</span>
          <span className="flex items-center gap-1"><span className="w-3 h-3 rounded" style={{ backgroundColor: '#fef08a' }} /> 55-69%</span>
          <span className="flex items-center gap-1"><span className="w-3 h-3 rounded" style={{ backgroundColor: '#fed7aa' }} /> 40-54%</span>
          <span className="flex items-center gap-1"><span className="w-3 h-3 rounded" style={{ backgroundColor: '#fecaca' }} /> &lt;40%</span>
        </div>
      </div>
    </div>
  );
};

export default FacultyView;
