import React, { useState } from 'react';
import { FileText } from 'lucide-react';
import Modal from '../modal/Modal';
import GenericForms from '../generic-forms/GenericForms';
import './DynamicCards.css';

interface CategoryWithStats {
  id: string;
  _id?: string;
  name: string;
  description?: string;
  parameterCount?: number;
  submittedCount?: number;
}

interface DynamicCardsProps {
  categories: CategoryWithStats[];
  className?: string;
  style?: React.CSSProperties;
  onRefresh?: () => void;
}

const DynamicCards: React.FC<DynamicCardsProps> = ({
  categories,
  className = '',
  style,
  onRefresh
}) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [selectedCategory, setSelectedCategory] = useState<string>('');

  const handleCategoryClick = (category: CategoryWithStats) => {
    setSelectedCategory(category.name);
    setIsModalOpen(true);
  };

  const handleModalClose = () => {
    setIsModalOpen(false);
    setSelectedCategory('');
  };

  return (
    <div className={`dynamic-cards-container ${className}`} style={style}>
      {categories.length > 0 ? (
        categories.map((category) => (
          <div key={category.id || category._id} className="category-card-wrapper">
            <div className="category-card" onClick={() => handleCategoryClick(category)}>
              <div className="category-card-header">
                <div className="category-title">{category.name}</div>
              </div>
              <div className="category-card-content">
                <button className="category-action-btn">
                  Submit Rating
                </button>
              </div>
            </div>
          </div>
        ))
      ) : (
        <div className="no-categories">
          <div className="no-data-card">
            <div className="no-data-content">
              <FileText className="no-data-icon" />
              <h3>No Categories Available</h3>
              <p>Categories will appear here once they are configured.</p>
            </div>
          </div>
        </div>
      )}

      <Modal
        isOpen={isModalOpen}
        onClose={handleModalClose}
        className="forms-modal"
      >
        {selectedCategory && (
          <GenericForms
            key={selectedCategory}
            categoryName={selectedCategory}
            onClose={handleModalClose}
            onSuccess={() => onRefresh?.()}
          />
        )}
      </Modal>
    </div>
  );
};

export default DynamicCards;
