function makeDept(
  id: number, code: string, name: string, facultyId: number,
  totalExpected: number, totalSubmitted: number, targetValuesLocked: number, actualsSubmitted: number,
): DepartmentSubmission {
  const completionPct = Math.round((totalSubmitted / totalExpected) * 100);
  let status: 'complete' | 'partial' | 'not-started' = 'partial';
  if (completionPct >= 95) status = 'complete';
  else if (completionPct === 0) status = 'not-started';
  return { id, code, name, facultyId, totalExpected, totalSubmitted, targetValuesLocked, actualsSubmitted, completionPct, status };
}

