function buildFaculty(id: number, name: string, code: string, departments: DepartmentSubmission[]): FacultySubmissionSummary {
  const totalExpected = departments.reduce((s, d) => s + d.totalExpected, 0);
  const totalSubmitted = departments.reduce((s, d) => s + d.totalSubmitted, 0);
  return {
    id, name, code, departments, totalExpected, totalSubmitted,
    completionPct: Math.round((totalSubmitted / totalExpected) * 100),
    deptComplete: departments.filter(d => d.status === 'complete').length,
    deptPartial: departments.filter(d => d.status === 'partial').length,
    deptNotStarted: departments.filter(d => d.status === 'not-started').length,
  };
}

