// ── Heatmap: Pillar × Faculty × Year ──

function seededRandom(seed: number): number {
  const x = Math.sin(seed * 9301 + 49297) * 49297;
  return x - Math.floor(x);
}

export const heatmapData: HeatmapCell[] = [];
cycleYears.forEach(year => {
  faculties.forEach(faculty => {
    pillarStatus.forEach(pillar => {
      const basePct = faculty.completionPct;
      const pillarBias = pillar.completionRate;
      const seed = faculty.id * 1000 + pillar.id * 10 + year;
      const jitter = (seededRandom(seed) - 0.5) * 30;
      let value = Math.max(5, Math.min(100, Math.round(basePct * 0.4 + pillarBias * 0.4 + jitter * 0.2 + jitter)));
      // Future years have no data
      if (year > activeYear) value = 0;
      // Past years have higher completion
      if (year < activeYear) value = Math.min(100, value + Math.round(seededRandom(seed + 999) * 15));
      heatmapData.push({
        pillar: pillar.name, pillarShort: pillar.shortName,
        faculty: faculty.name, facultyCode: faculty.code,
        value, year,
      });
    });
  });
});

// ── Target vs Actual Performance ──
// Each parameter has its own scale (counts, percentages, currency, etc.)
// So we track: per parameter, is actual >= projected for that year?
// Breakdown = count of parameters in each status bucket

export interface PerformanceBreakdown {
  exceeding: number;   // actual > projected (doing better than target)
  meeting: number;     // actual ≈ projected (within 5%)
  below: number;       // actual < projected
  noActualYet: number; // targets locked but no actual submitted for active year
  noTargetYet: number; // targets not yet locked
}

export interface PillarPerformance {
  pillarId: number;
  shortName: string;
  totalParams: number;
  breakdown: PerformanceBreakdown;
  onTrackPct: number; // (exceeding + meeting) / (exceeding + meeting + below) * 100
}

export interface DepartmentPerformance {
  id: number;
  code: string;
  name: string;
  facultyId: number;
  totalParams: number;
  breakdown: PerformanceBreakdown;
  onTrackPct: number;
}

function computeBreakdown(
  totalParams: number, targetsLocked: number, actualsSubmitted: number, seed: number,
): PerformanceBreakdown {
  const r = (s: number) => { const x = Math.sin(s * 9301 + 49297) * 49297; return x - Math.floor(x); };
  const noTargetYet = totalParams - targetsLocked;
  const noActualYet = targetsLocked - actualsSubmitted;
  const withBoth = actualsSubmitted;
  const exceeding = Math.round(withBoth * (0.18 + r(seed) * 0.15));
  const meeting = Math.round(withBoth * (0.30 + r(seed + 1) * 0.12));
  const below = Math.max(0, withBoth - exceeding - meeting);
  return { exceeding, meeting, below, noActualYet: Math.max(0, noActualYet), noTargetYet: Math.max(0, noTargetYet) };
}

function onTrackPct(b: PerformanceBreakdown): number {
  const tracked = b.exceeding + b.meeting + b.below;
  return tracked > 0 ? Math.round((b.exceeding + b.meeting) / tracked * 100) : 0;
}

export const departmentPerformance: DepartmentPerformance[] = allDepartments.map((d, i) => {
  const breakdown = computeBreakdown(d.totalExpected, d.targetValuesLocked, d.actualsSubmitted, d.id * 100 + i);
  return {
    id: d.id, code: d.code, name: d.name, facultyId: d.facultyId,
    totalParams: d.totalExpected, breakdown, onTrackPct: onTrackPct(breakdown),
  };
});

export const pillarPerformance: PillarPerformance[] = pillarStatus.map(p => {
  const r = (s: number) => { const x = Math.sin(s * 9301 + 49297) * 49297; return x - Math.floor(x); };
  const seed = p.id * 77;
  const totalParams = p.totalParameters * allDepartments.length;
  const withTargets = Math.round(totalParams * (p.completionRate / 100) * (0.85 + r(seed) * 0.1));
  const withActuals = Math.round(withTargets * (0.55 + r(seed + 1) * 0.25));
  const breakdown = computeBreakdown(totalParams, withTargets, withActuals, seed + 2);
  return {
    pillarId: p.id, shortName: p.shortName,
    totalParams, breakdown, onTrackPct: onTrackPct(breakdown),
  };
});

// University-wide performance summary
const allBreakdowns = departmentPerformance.map(d => d.breakdown);
export const universityPerformance: PerformanceBreakdown = {
  exceeding: allBreakdowns.reduce((s, b) => s + b.exceeding, 0),
  meeting: allBreakdowns.reduce((s, b) => s + b.meeting, 0),
  below: allBreakdowns.reduce((s, b) => s + b.below, 0),
  noActualYet: allBreakdowns.reduce((s, b) => s + b.noActualYet, 0),
  noTargetYet: allBreakdowns.reduce((s, b) => s + b.noTargetYet, 0),
};

export const universityOnTrackPct = onTrackPct(universityPerformance);

